(307987,34221,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони вишиковують ... дві пари капців-монстриків.'::text,'свої'::text,'наші'::text,'свої'::text,'Вони вишиковують свої дві пари капців-монстриків.'::text),
