(295842,32872,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... er eine gefrorene Wand hoch. Total entspannend, klar.'::text,'kletterte'::text,'klettert'::text,'klettern'::text,'Gestern kletterte er eine gefrorene Wand hoch. Total entspannend, klar.'::text),
(295846,32872,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора він ... на замерзлу стіну. Суцільний релакс, звісно.'::text,'ліз'::text,'лізе'::text,'лізти'::text,'Учора він ліз на замерзлу стіну. Суцільний релакс, звісно.'::text),
(295845,32872,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer él ... un muro helado. Relajante, obviamente.'::text,'escaló'::text,'escala'::text,'escalar'::text,'Ayer él escaló un muro helado. Relajante, obviamente.'::text),
(295844,32872,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, il ... un mur gelé. Reposant, évidemment.'::text,'a escaladé'::text,'escalade'::text,'escalader'::text,'Hier, il a escaladé un mur gelé. Reposant, évidemment.'::text),
(295847,32872,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün donmuş bir duvara ..., rahatlatıcı tabii ki.'::text,'tırmandı'::text,'tırmanır'::text,'tırmanmak'::text,'Dün donmuş bir duvara tırmandı, rahatlatıcı tabii ki.'::text),
(295848,32872,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap ... egy jéggé fagyott falra. Nyilván nagyon pihentető.'::text,'felmászott'::text,'felmászik'::text,'felmászni'::text,'Tegnap felmászott egy jéggé fagyott falra. Nyilván nagyon pihentető.'::text),
(295851,32873,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hasst Eis, aber gestern ... er eine gefrorene Wand hoch. Horror!'::text,'kletterte'::text,'klettert'::text,NULL::text,'Er hasst Eis, aber gestern kletterte er eine gefrorene Wand hoch. Horror!'::text),
(295855,32873,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ненавидить лід, але вчора він ... на замерзлу стіну. Жах!'::text,'ліз'::text,'лізе'::text,NULL::text,'Він ненавидить лід, але вчора він ліз на замерзлу стіну. Жах!'::text),
(295854,32873,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Odia el hielo, pero ayer ... un muro helado. ¡Aterrador!'::text,'escaló'::text,'escala'::text,NULL::text,'Odia el hielo, pero ayer escaló un muro helado. ¡Aterrador!'::text),
(295853,32873,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il déteste la glace, mais hier il ... un mur gelé. Terrifiant !'::text,'a escaladé'::text,'escalade'::text,NULL::text,'Il déteste la glace, mais hier il a escaladé un mur gelé. Terrifiant !'::text),
(295856,32873,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buzdan nefret ediyor ama dün donmuş bir duvara ...! Korkunç!'::text,'tırmandı'::text,'tırmanır'::text,NULL::text,'Buzdan nefret ediyor ama dün donmuş bir duvara tırmandı! Korkunç!'::text),
(295857,32873,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Utálja a jeget, de tegnap ... egy jéggé fagyott falra. Rémisztő!'::text,'felmászott'::text,'felmászik'::text,NULL::text,'Utálja a jeget, de tegnap felmászott egy jéggé fagyott falra. Rémisztő!'::text),
(295860,32874,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kletterer ... jetzt die gefrorene Wand hoch.'::text,'klettert'::text,'klettert'::text,'klettert'::text,'Der Kletterer klettert jetzt die gefrorene Wand hoch.'::text),
(295864,32874,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Альпініст зараз ... замерзлою стіною вгору.'::text,'лізе'::text,'лізе'::text,'лізе'::text,'Альпініст зараз лізе замерзлою стіною вгору.'::text),
(295863,32874,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El escalador ... el muro helado ahora.'::text,'está escalando'::text,'escala'::text,'está escalando'::text,'El escalador está escalando el muro helado ahora.'::text),
(295862,32874,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le grimpeur ... le mur gelé en ce moment.'::text,'est en train d''escalader'::text,'escalade'::text,'est en train d''escalader'::text,'Le grimpeur est en train d''escalader le mur gelé en ce moment.'::text),
(295865,32874,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dağcı şu an donmuş duvara ...'::text,'tırmanıyor'::text,'tırmanır'::text,'tırmanıyor'::text,'Dağcı şu an donmuş duvara tırmanıyor.'::text),
(295866,32874,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mászó most ... a jéggé fagyott falra.'::text,'mászik fel'::text,'mászik fel'::text,'mászik fel'::text,'A mászó most mászik fel a jéggé fagyott falra.'::text),
(295869,32875,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise klettert er am Fels, aber heute ... er an einer gefrorenen Wand.'::text,'klettert'::text,'klettert'::text,NULL::text,'Normalerweise klettert er am Fels, aber heute klettert er an einer gefrorenen Wand.'::text),
(295873,32875,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай він лазить по скелях, але сьогодні він ... по замерзлій стіні.'::text,'лізе'::text,'лізе'::text,NULL::text,'Зазвичай він лазить по скелях, але сьогодні він лізе по замерзлій стіні.'::text),
(295872,32875,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente escala en roca, pero hoy ... un muro helado.'::text,'está escalando'::text,'escala'::text,NULL::text,'Normalmente escala en roca, pero hoy está escalando un muro helado.'::text),
(295871,32875,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude il grimpe sur du rocher, mais aujourd''hui il ... un mur gelé.'::text,'est en train d''escalader'::text,'escalade'::text,NULL::text,'D''habitude il grimpe sur du rocher, mais aujourd''hui il est en train d''escalader un mur gelé.'::text),
(295874,32875,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde kayaya tırmanır ama bugün donmuş bir duvara ...'::text,'tırmanıyor'::text,'tırmanır'::text,NULL::text,'Genelde kayaya tırmanır ama bugün donmuş bir duvara tırmanıyor.'::text),
(295875,32875,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában sziklát mászik, de ma egy jéggé fagyott falat ...'::text,'mászik'::text,'mászik'::text,NULL::text,'Általában sziklát mászik, de ma egy jéggé fagyott falat mászik.'::text),
(295887,32877,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mutiger Plan, ehrlich: Du ... heute die ganze gefrorene Wand hochklettern.'::text,'wirst'::text,'wirst'::text,'wirst'::text,'Mutiger Plan, ehrlich: Du wirst heute die ganze gefrorene Wand hochklettern.'::text),
(295891,32877,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сміливий план, чесно: ти сьогодні ... на всю замерзлу стіну.'::text,'збираєшся вилізти'::text,'вилізеш'::text,'збираєшся вилізти'::text,'Сміливий план, чесно: ти сьогодні збираєшся вилізти на всю замерзлу стіну.'::text),
(295890,32877,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan atrevido, la verdad: hoy ... todo el muro helado.'::text,'vas a escalar'::text,'escalarás'::text,'vas a escalar'::text,'Plan atrevido, la verdad: hoy vas a escalar todo el muro helado.'::text),
(295889,32877,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan audacieux, franchement : aujourd''hui, tu ... tout le mur gelé.'::text,'vas escalader'::text,'escaladeras'::text,'vas escalader'::text,'Plan audacieux, franchement : aujourd''hui, tu vas escalader tout le mur gelé.'::text),
(295892,32877,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cesur plan, cidden: bugün donmuş duvarın tamamına ...'::text,'tırmanacaksın'::text,'tırmanacaksın'::text,'tırmanacaksın'::text,'Cesur plan, cidden: bugün donmuş duvarın tamamına tırmanacaksın.'::text),
(295893,32877,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Merész terv, őszintén: ma meg ... mászni az egész jéggé fagyott falat.'::text,'fogod'::text,'fogod'::text,'fogod'::text,'Merész terv, őszintén: ma meg fogod mászni az egész jéggé fagyott falat.'::text),
(295896,32878,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine makellose Wahl: Die gefrorene Wand ist ... als der leichte Weg.'::text,'steiler'::text,'steiler'::text,'am steilsten'::text,'Eine makellose Wahl: Die gefrorene Wand ist steiler als der leichte Weg.'::text),
(295900,32878,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний вибір: замерзла стіна ... за легку стежку.'::text,'крутіша'::text,'більш крута'::text,'найкрутіша'::text,'Бездоганний вибір: замерзла стіна крутіша за легку стежку.'::text),
(295899,32878,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una elección impecable: el muro helado es ... que el camino fácil.'::text,'más empinado'::text,'más empinado'::text,'el más empinado'::text,'Una elección impecable: el muro helado es más empinado que el camino fácil.'::text),
