(295901,32878,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz bir seçim: donmuş duvar kolay yoldan ...'::text,'daha dik'::text,'daha dik'::text,'en dik'::text,'Kusursuz bir seçim: donmuş duvar kolay yoldan daha dik.'::text),
(295902,32878,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan választás: a jéggé fagyott fal ..., mint a könnyű ösvény.'::text,'meredekebb'::text,'meredekebb'::text,'legmeredekebb'::text,'Hibátlan választás: a jéggé fagyott fal meredekebb, mint a könnyű ösvény.'::text),
(303564,33730,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Enten laufen in einer Reihe ... dem Kiesweg.'::text,'auf'::text,'an'::text,'in'::text,'Die Enten laufen in einer Reihe auf dem Kiesweg.'::text),
(303568,33730,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Качки йдуть рядочком ... гравійній стежці.'::text,'по'::text,'біля'::text,'у'::text,'Качки йдуть рядочком по гравійній стежці.'::text),
(303567,33730,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los patos caminan en fila ... el camino de grava.'::text,'por'::text,'a'::text,'en'::text,'Los patos caminan en fila por el camino de grava.'::text),
(303566,33730,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les canards marchent en file ... le chemin de gravier.'::text,'sur'::text,'à'::text,'dans'::text,'Les canards marchent en file sur le chemin de gravier.'::text),
(303569,33730,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ördekler çakıllı yolun ... tek sıra hâlinde yürüyor.'::text,'üzerinde'::text,NULL::text,'içinde'::text,'Ördekler çakıllı yolun üzerinde tek sıra hâlinde yürüyor.'::text),
(303570,33730,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kacsák libasorban mennek a kavicsos ...'::text,'ösvényen'::text,'ösvénynél'::text,'ösvényben'::text,'A kacsák libasorban mennek a kavicsos ösvényen.'::text),
(303591,33733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Enten laufen in einer Reihe, weil auf dem Weg nicht viel ... ist.'::text,'Platz'::text,'Platz'::text,'ein Platz'::text,'Die Enten laufen in einer Reihe, weil auf dem Weg nicht viel Platz ist.'::text),
(303595,33733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Качки йдуть рядочком, бо на стежці не так багато ...'::text,'місця'::text,'місць'::text,'місця'::text,'Качки йдуть рядочком, бо на стежці не так багато місця.'::text),
(303594,33733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los patos caminan en fila porque no hay mucho ... en el camino.'::text,'espacio'::text,'espacio'::text,'un espacio'::text,'Los patos caminan en fila porque no hay mucho espacio en el camino.'::text),
(303593,33733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les canards marchent en file parce qu''il n''y a pas beaucoup de ... sur le chemin.'::text,'place'::text,'place'::text,'une place'::text,'Les canards marchent en file parce qu''il n''y a pas beaucoup de place sur le chemin.'::text),
(303596,33733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ördekler sıra hâlinde yürüyor çünkü yolda çok fazla ... yok.'::text,'yer'::text,'yerler'::text,'bir yer'::text,'Ördekler sıra hâlinde yürüyor çünkü yolda çok fazla yer yok.'::text),
(303597,33733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kacsák libasorban mennek, mert nincs sok ... az ösvényen.'::text,'hely'::text,'hely'::text,'egy hely'::text,'A kacsák libasorban mennek, mert nincs sok hely az ösvényen.'::text),
(303600,33734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Reihe hat ... Enten, weil eine Reihe aus Enten besteht.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Die Reihe hat viele Enten, weil eine Reihe aus Enten besteht.'::text),
(303604,33734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У ряду ... качок, бо ряд складається з качок.'::text,'багато'::text,'багато'::text,'будь-яких'::text,'У ряду багато качок, бо ряд складається з качок.'::text),
(303603,33734,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fila tiene ... patos porque una fila está hecha de patos.'::text,'muchos'::text,'mucho'::text,'cualquier'::text,'La fila tiene muchos patos porque una fila está hecha de patos.'::text),
(303602,33734,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La file a ... canards parce qu''une file est faite de canards.'::text,'beaucoup de'::text,'beaucoup de'::text,'n''importe quels'::text,'La file a beaucoup de canards parce qu''une file est faite de canards.'::text),
(303605,33734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırada ... ördek var çünkü sıra ördeklerden oluşur.'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Sırada çok ördek var çünkü sıra ördeklerden oluşur.'::text),
(303606,33734,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sorban ... kacsa van, mert a sor kacsákból áll.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'A sorban sok kacsa van, mert a sor kacsákból áll.'::text),
(303609,33735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, angeblich ... zwanzig Enten in dieser einen Reihe.'::text,'sind'::text,'ist'::text,'sein'::text,'Rate mal, angeblich sind zwanzig Enten in dieser einen Reihe.'::text),
(303613,33735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, у тому одному ряду ... двадцять качок.'::text,'є'::text,'є'::text,'бути'::text,'Уяви, кажуть, у тому одному ряду є двадцять качок.'::text),
(303612,33735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, dicen que ... veinte patos en esa sola fila.'::text,'hay'::text,'hay'::text,'hay'::text,'Adivina qué, dicen que hay veinte patos en esa sola fila.'::text),
(303611,33735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, paraît-il, ... vingt canards dans cette seule file.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Devine quoi, paraît-il, il y a vingt canards dans cette seule file.'::text),
(303614,33735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, dediklerine göre o tek sırada yirmi ördek ...'::text,'var'::text,'var'::text,'olmak'::text,'Bil bakalım, dediklerine göre o tek sırada yirmi ördek var.'::text),
(303615,33735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondják, abban az egy sorban húsz kacsa ...'::text,'van'::text,'van'::text,'lenni'::text,'Képzeld, azt mondják, abban az egy sorban húsz kacsa van.'::text),
(303618,33736,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab die Hofregel gehört: Die Enten ... in einer Reihe laufen.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Mädel, ich hab die Hofregel gehört: Die Enten müssen in einer Reihe laufen.'::text),
(303622,33736,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула правило ферми: качки ... ходити рядочком.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Подруго, я чула правило ферми: качки мають ходити рядочком.'::text),
(303621,33736,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me he enterado de la norma de la granja: los patos ... caminar en fila.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Tía, me he enterado de la norma de la granja: los patos tienen que caminar en fila.'::text),
(303620,33736,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu la règle de la ferme : les canards ... marcher en file.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Ma belle, j''ai entendu la règle de la ferme : les canards doivent marcher en file.'::text),
(303623,33736,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, çiftliğin kuralını duydum: ördekler sıra hâlinde ...'::text,'yürümek zorunda'::text,'yürümeli'::text,'yürümeli'::text,'Kızım, çiftliğin kuralını duydum: ördekler sıra hâlinde yürümek zorunda.'::text),
(303624,33736,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, hallottam a farm szabályát: a kacsáknak libasorban ... menniük.'::text,'kell'::text,'kell'::text,'kellene'::text,'Csajszi, hallottam a farm szabályát: a kacsáknak libasorban kell menniük.'::text),
(303627,33737,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Reihe ist lang, also ... die Enten auf dem Weg bleiben.'::text,'sollten'::text,'sollten'::text,'sollten'::text,'Die Reihe ist lang, also sollten die Enten auf dem Weg bleiben.'::text),
(303631,33737,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ряд довгий, тож качки ... залишатися на стежці.'::text,'мали б'::text,'мали б'::text,'мали б'::text,'Ряд довгий, тож качки мали б залишатися на стежці.'::text),
(303630,33737,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fila es larga, así que los patos ... quedarse en el camino.'::text,'deberían'::text,'deberían'::text,'deberían'::text,'La fila es larga, así que los patos deberían quedarse en el camino.'::text),
(303629,33737,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La file est longue, donc les canards ... rester sur le chemin.'::text,'devraient'::text,'devraient'::text,'devraient'::text,'La file est longue, donc les canards devraient rester sur le chemin.'::text),
(303632,33737,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıra uzun, bu yüzden ördekler yolda ...'::text,'kalmalı'::text,'kalmalı'::text,'kalmalı'::text,'Sıra uzun, bu yüzden ördekler yolda kalmalı.'::text),
(303633,33737,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sor hosszú, ezért a kacsáknak az ösvényen ... maradniuk.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'A sor hosszú, ezért a kacsáknak az ösvényen kellene maradniuk.'::text),
(314472,34942,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagesziel: Der grüne Motorroller ... 2 Hunde den Feldweg entlang.'::text,'transportiert'::text,'transportieren'::text,'transportierend'::text,'Tagesziel: Der grüne Motorroller transportiert 2 Hunde den Feldweg entlang.'::text),
(314476,34942,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Денна ціль: зелений скутер ... 2 собак стежкою.'::text,'везе'::text,'везти'::text,'везучи'::text,'Денна ціль: зелений скутер везе 2 собак стежкою.'::text),
(314475,34942,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo diario: el escúter verde ... 2 perros por el camino.'::text,'lleva'::text,'llevar'::text,'llevando'::text,'Objetivo diario: el escúter verde lleva 2 perros por el camino.'::text),
(314474,34942,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif du jour : le scooter vert ... 2 chiens le long du chemin.'::text,'transporte'::text,'transporter'::text,'transportant'::text,'Objectif du jour : le scooter vert transporte 2 chiens le long du chemin.'::text),
(314477,34942,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Günlük hedef: yeşil scooter 2 köpeği patika boyunca ...'::text,'taşır'::text,'taşımak'::text,'taşıyarak'::text,'Günlük hedef: yeşil scooter 2 köpeği patika boyunca taşır.'::text),
(314478,34942,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napi cél: a zöld robogó 2 kutyát ... végig az úton.'::text,'visz'::text,'vinni'::text,'vivő'::text,'Napi cél: a zöld robogó 2 kutyát visz végig az úton.'::text),
(314481,34943,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Die Hunde ... Motorroller fahren, aber ihn nicht anhalten!'::text,'können'::text,'können'::text,'sind'::text,'Katastrophe! Die Hunde können Motorroller fahren, aber ihn nicht anhalten!'::text),
(314485,34943,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Собаки ... їздити на скутері, але не зупинити його!'::text,'можуть'::text,'можуть'::text,'є'::text,'Катастрофа! Собаки можуть їздити на скутері, але не зупинити його!'::text),
(314484,34943,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Los perros ... ir en escúter, pero no pararlo!'::text,'pueden'::text,'pueden'::text,'están'::text,'¡Desastre! ¡Los perros pueden ir en escúter, pero no pararlo!'::text),
(314483,34943,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Les chiens ... conduire un scooter, mais pas l''arrêter !'::text,'peuvent'::text,'peuvent'::text,'sont'::text,'Catastrophe ! Les chiens peuvent conduire un scooter, mais pas l''arrêter !'::text),
(314486,34943,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Köpekler scooter ... ama onu durduramazlar!'::text,'sürebilir'::text,'sürebilir'::text,NULL::text,'Felaket! Köpekler scooter sürebilir ama onu durduramazlar!'::text),
(314487,34943,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A kutyák ... robogózni, de megállítani nem!'::text,'tudnak'::text,'tudnak'::text,'vannak'::text,'Katasztrófa! A kutyák tudnak robogózni, de megállítani nem!'::text),
(314490,34944,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Ein kleiner Motorroller und ... fallen ins Schilf!'::text,'zwei Hunde'::text,'zwei Hund'::text,'zwei Hunde'::text,'Albtraum! Ein kleiner Motorroller und zwei Hunde fallen ins Schilf!'::text),
(314494,34944,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Один маленький скутер і ... падають в очерет!'::text,'два пси'::text,'два пес'::text,'два пси'::text,'Жах! Один маленький скутер і два пси падають в очерет!'::text),
(314493,34944,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Un escúter pequeño y ... caen a los juncos!'::text,'dos perros'::text,'dos perro'::text,'dos perros'::text,'¡Pesadilla! ¡Un escúter pequeño y dos perros caen a los juncos!'::text),
(314492,34944,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Un petit scooter et ... tombent dans les roseaux !'::text,'deux chiens'::text,'deux chien'::text,'deux chiens'::text,'Cauchemar ! Un petit scooter et deux chiens tombent dans les roseaux !'::text),
(314495,34944,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Küçük bir scooter ve ... sazlıklara düşüyor!'::text,'iki köpek'::text,'iki köpek'::text,'iki köpek'::text,'Kâbus! Küçük bir scooter ve iki köpek sazlıklara düşüyor!'::text),
(314496,34944,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Egy kis robogó és ... beesik a nádasba!'::text,'két kutya'::text,'két kutya'::text,'két kutya'::text,'Rémálom! Egy kis robogó és két kutya beesik a nádasba!'::text),
(314499,34945,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei Hunde fahren auf einem Motorroller. Katastrophe: ... Motorroller kippt um!'::text,'der'::text,'ein'::text,'ein'::text,'Zwei Hunde fahren auf einem Motorroller. Katastrophe: der Motorroller kippt um!'::text),
(314503,34945,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Два пси їдуть на скутері. Катастрофа: ... скутер перекидається!'::text,''::text,NULL::text,NULL::text,'Два пси їдуть на скутері. Катастрофа: скутер перекидається!'::text),
(314502,34945,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dos perros van en un escúter. ¡Qué desastre: ... escúter se vuelca!'::text,'el'::text,'un'::text,'un'::text,'Dos perros van en un escúter. ¡Qué desastre: el escúter se vuelca!'::text),
(314501,34945,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux chiens roulent en scooter. Catastrophe : ... scooter se renverse !'::text,'le'::text,'un'::text,'un'::text,'Deux chiens roulent en scooter. Catastrophe : le scooter se renverse !'::text),
(314504,34945,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki köpek bir scooter sürüyor. Felaket: ... scooter devriliyor!'::text,''::text,'bir'::text,'bir'::text,'İki köpek bir scooter sürüyor. Felaket: scooter devriliyor!'::text),
(314505,34945,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két kutya robogózik. Katasztrófa: ... robogó felborul!'::text,'a'::text,'egy'::text,'egy'::text,'Két kutya robogózik. Katasztrófa: a robogó felborul!'::text),
(314508,34946,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Motorroller ist grün, also ist er ein grüner Motorroller.'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Dieser Motorroller ist grün, also ist er ein grüner Motorroller.'::text),
(314512,34946,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... скутер зелений, тож це зелений скутер.'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей скутер зелений, тож це зелений скутер.'::text),
(314511,34946,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... escúter es verde, así que es un escúter verde.'::text,'Este'::text,'Estos'::text,'Esos'::text,'Este escúter es verde, así que es un escúter verde.'::text),
(314510,34946,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... scooter est vert, donc c''est un scooter vert.'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Ce scooter est vert, donc c''est un scooter vert.'::text),
(314513,34946,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... scooter yeşil, yani yeşil bir scooter.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu scooter yeşil, yani yeşil bir scooter.'::text),
(314514,34946,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a robogó zöld, tehát ez egy zöld robogó.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a robogó zöld, tehát ez egy zöld robogó.'::text),
(314517,34947,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die zwei Hunde steigen von ... Motorroller ab und laufen herum.'::text,'ihrem'::text,'seinem'::text,'seinem'::text,'Die zwei Hunde steigen von ihrem Motorroller ab und laufen herum.'::text),
(314521,34947,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Два пси злазять зі ... скутера й бродять навколо.'::text,'свого'::text,'свого'::text,'свого'::text,'Два пси злазять зі свого скутера й бродять навколо.'::text),
(314520,34947,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los dos perros se bajan de ... escúter y dan vueltas.'::text,'su'::text,'su'::text,'su'::text,'Los dos perros se bajan de su escúter y dan vueltas.'::text),
(314519,34947,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux chiens descendent de ... scooter et se baladent.'::text,'leur'::text,'son'::text,'son'::text,'Les deux chiens descendent de leur scooter et se baladent.'::text),
(314522,34947,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki köpek ... scooterından iniyor ve etrafta dolaşıyor.'::text,'onların'::text,'onun'::text,'onun'::text,'İki köpek onların scooterından iniyor ve etrafta dolaşıyor.'::text),
(314523,34947,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két kutya leszáll a ... és körbejárkál.'::text,'robogójukról'::text,'robogójáról'::text,'robogójáról'::text,'A két kutya leszáll a robogójukról és körbejárkál.'::text),
(314526,34948,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fällt der Motorroller? Ins hohe Schilf.'::text,'Wohin'::text,'Wann'::text,'Wer'::text,'Wohin fällt der Motorroller? Ins hohe Schilf.'::text),
(314530,34948,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... падає скутер? У високий очерет.'::text,'Куди'::text,'Коли'::text,'Хто'::text,'Куди падає скутер? У високий очерет.'::text),
(314529,34948,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... cae el escúter? A los juncos altos.'::text,'Dónde'::text,'Cuándo'::text,'Quién'::text,'¿Dónde cae el escúter? A los juncos altos.'::text),
(314528,34948,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le scooter tombe-t-il ? Dans les hauts roseaux.'::text,'Où'::text,'Quand'::text,'Qui'::text,'Où le scooter tombe-t-il ? Dans les hauts roseaux.'::text),
(314531,34948,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Scooter ... düşüyor? Uzun sazlıkların içine.'::text,'nereye'::text,'ne zaman'::text,'kim'::text,'Scooter nereye düşüyor? Uzun sazlıkların içine.'::text),
(314532,34948,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... esik a robogó? A magas nádasba.'::text,'Hová'::text,'Mikor'::text,'Ki'::text,'Hová esik a robogó? A magas nádasba.'::text),
(326487,36277,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund ... den Frosch ewig lang, und dann entkam er für immer!'::text,'beobachtete'::text,'beobachtet'::text,'beobachtend'::text,'Der Hund beobachtete den Frosch ewig lang, und dann entkam er für immer!'::text),
(326491,36277,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес ... за жабою цілу вічність, а потім вона втекла назавжди!'::text,'стежив'::text,'стежить'::text,'стежачи'::text,'Пес стежив за жабою цілу вічність, а потім вона втекла назавжди!'::text),
(326490,36277,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El perro ... a la rana durante siglos, y luego se escapó para siempre!'::text,'observó'::text,'observa'::text,'observando'::text,'¡El perro observó a la rana durante siglos, y luego se escapó para siempre!'::text),
(326489,36277,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien ... la grenouille pendant des lustres, et puis elle s''est échappée pour toujours !'::text,'a observé'::text,'observe'::text,'observant'::text,'Le chien a observé la grenouille pendant des lustres, et puis elle s''est échappée pour toujours !'::text),
(326492,36277,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek kurbağayı saatlerce ..., sonra kurbağa sonsuza dek kaçtı!'::text,'izledi'::text,'izler'::text,'izleyerek'::text,'Köpek kurbağayı saatlerce izledi, sonra kurbağa sonsuza dek kaçtı!'::text),
(326493,36277,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya egy örökkévalóságig ... a békát, aztán az örökre megszökött!'::text,'figyelte'::text,'figyeli'::text,'figyelő'::text,'A kutya egy örökkévalóságig figyelte a békát, aztán az örökre megszökött!'::text),
(326496,36278,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund ... normalerweise Frösche, weil Frösche zum Beobachten da sind.'::text,'beobachtet'::text,'beobachtete'::text,NULL::text,'Der Hund beobachtet normalerweise Frösche, weil Frösche zum Beobachten da sind.'::text),
(326500,36278,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес зазвичай ... за жабами, бо жаби для того, щоб за ними стежити.'::text,'стежить'::text,'стежив'::text,NULL::text,'Пес зазвичай стежить за жабами, бо жаби для того, щоб за ними стежити.'::text),
(326499,36278,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro normalmente ... ranas, porque las ranas son para observarlas.'::text,'observa'::text,'observó'::text,NULL::text,'El perro normalmente observa ranas, porque las ranas son para observarlas.'::text),
(326498,36278,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, le chien ... les grenouilles, parce que les grenouilles, c''est fait pour être observé.'::text,'observe'::text,'a observé'::text,NULL::text,'D''habitude, le chien observe les grenouilles, parce que les grenouilles, c''est fait pour être observé.'::text),
(326501,36278,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek genelde kurbağaları ..., çünkü kurbağalar izlemek içindir.'::text,'izler'::text,'izledi'::text,NULL::text,'Köpek genelde kurbağaları izler, çünkü kurbağalar izlemek içindir.'::text),
(326502,36278,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya általában ... a békákat, mert a békák arra valók, hogy figyeljük őket.'::text,'figyeli'::text,'figyelte'::text,NULL::text,'A kutya általában figyeli a békákat, mert a békák arra valók, hogy figyeljük őket.'::text),
(326505,36279,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau! Der Hund ... den Frosch, weil seine Augen offen sind.'::text,'beobachtet'::text,'beobachtet'::text,'beobachtet'::text,'Schau! Der Hund beobachtet den Frosch, weil seine Augen offen sind.'::text),
(326509,36279,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дивись! Пес ... за жабою, бо в нього розплющені очі.'::text,'стежить'::text,'стежить'::text,'стежить'::text,'Дивись! Пес стежить за жабою, бо в нього розплющені очі.'::text),
(326508,36279,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mira! El perro ... a la rana, porque tiene los ojos abiertos.'::text,'está observando'::text,'observa'::text,'está observando'::text,'¡Mira! El perro está observando a la rana, porque tiene los ojos abiertos.'::text),
(326507,36279,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde ! Le chien ... la grenouille, parce que ses yeux sont ouverts.'::text,'est en train d''observer'::text,'observe'::text,'est en train d''observer'::text,'Regarde ! Le chien est en train d''observer la grenouille, parce que ses yeux sont ouverts.'::text),
(326510,36279,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bak! Köpek kurbağayı ..., çünkü gözleri açık.'::text,'izliyor'::text,'izler'::text,'izliyor'::text,'Bak! Köpek kurbağayı izliyor, çünkü gözleri açık.'::text),
(326511,36279,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézd! A kutya ... a békát, mert nyitva van a szeme.'::text,'figyeli'::text,'figyeli'::text,'figyeli'::text,'Nézd! A kutya figyeli a békát, mert nyitva van a szeme.'::text),
(326523,36281,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich glaube, dass der Hund den Frosch ..., bis er wegschwimmt.'::text,'beobachten wird'::text,'beobachtet'::text,'beobachtete'::text,'Ich glaube, dass der Hund den Frosch beobachten wird, bis er wegschwimmt.'::text),
(326527,36281,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Думаю, пес ... за жабою, доки вона не відпливе.'::text,'стежитиме'::text,'стежить'::text,'стежив'::text,'Думаю, пес стежитиме за жабою, доки вона не відпливе.'::text),
(326526,36281,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Creo que el perro ... a la rana hasta que se vaya nadando.'::text,'observará'::text,'observa'::text,'observó'::text,'Creo que el perro observará a la rana hasta que se vaya nadando.'::text),
(326525,36281,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je pense que le chien ... la grenouille jusqu''à ce qu''elle s''éloigne à la nage.'::text,'observera'::text,'observe'::text,'a observé'::text,'Je pense que le chien observera la grenouille jusqu''à ce qu''elle s''éloigne à la nage.'::text),
(326528,36281,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bence köpek kurbağayı yüzüp gidene kadar ...'::text,'izleyecek'::text,'izler'::text,'izledi'::text,'Bence köpek kurbağayı yüzüp gidene kadar izleyecek.'::text),
(326529,36281,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szerintem a kutya addig ... a békát, amíg el nem úszik.'::text,'fogja figyelni'::text,'figyeli'::text,'figyelte'::text,'Szerintem a kutya addig fogja figyelni a békát, amíg el nem úszik.'::text),
(326532,36282,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund hat einen Plan: Er ... den Frosch ganz genau beobachten.'::text,'wird'::text,'wird'::text,'beobachtet'::text,'Der Hund hat einen Plan: Er wird den Frosch ganz genau beobachten.'::text),
(326536,36282,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У пса є план: він ... за жабою дуже уважно.'::text,'збирається стежити'::text,'стежитиме'::text,'стежить'::text,'У пса є план: він збирається стежити за жабою дуже уважно.'::text),
(326535,36282,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro tiene un plan: ... a la rana con mucha atención.'::text,'va a observar'::text,'observará'::text,'observa'::text,'El perro tiene un plan: va a observar a la rana con mucha atención.'::text),
(326534,36282,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien a un plan : il ... la grenouille très attentivement.'::text,'va observer'::text,'observera'::text,'observe'::text,'Le chien a un plan : il va observer la grenouille très attentivement.'::text),
(326537,36282,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpeğin bir planı var: kurbağayı çok dikkatli ...'::text,'izleyecek'::text,'izleyecek'::text,'izler'::text,'Köpeğin bir planı var: kurbağayı çok dikkatli izleyecek.'::text),
(326538,36282,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutyának van egy terve: nagyon figyelmesen ... a békát.'::text,'fogja figyelni'::text,'fogja figyelni'::text,'figyeli'::text,'A kutyának van egy terve: nagyon figyelmesen fogja figyelni a békát.'::text),
(326541,36283,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Augen bewegen sich nie! Der Hund ... diesen Frosch für immer beobachten!'::text,'wird'::text,'wird'::text,NULL::text,'Diese Augen bewegen sich nie! Der Hund wird diesen Frosch für immer beobachten!'::text),
(326545,36283,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці очі ніколи не рухаються! Пес ... за тією жабою вічно!'::text,'збирається стежити'::text,'стежитиме'::text,NULL::text,'Ці очі ніколи не рухаються! Пес збирається стежити за тією жабою вічно!'::text),
(326544,36283,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esos ojos no se mueven nunca! ¡El perro ... a esa rana para siempre!'::text,'va a observar'::text,'observará'::text,NULL::text,'¡Esos ojos no se mueven nunca! ¡El perro va a observar a esa rana para siempre!'::text),
(326543,36283,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces yeux ne bougent jamais ! Le chien ... cette grenouille pour toujours !'::text,'va observer'::text,'observera'::text,NULL::text,'Ces yeux ne bougent jamais ! Le chien va observer cette grenouille pour toujours !'::text),
(326546,36283,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O gözler hiç kıpırdamıyor! Köpek o kurbağayı sonsuza dek ...!'::text,'izleyecek'::text,'izleyecek'::text,NULL::text,'O gözler hiç kıpırdamıyor! Köpek o kurbağayı sonsuza dek izleyecek!'::text),
(326547,36283,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azok a szemek sosem mozdulnak! A kutya örökké ... azt a békát!'::text,'fogja figyelni'::text,'fogja figyelni'::text,NULL::text,'Azok a szemek sosem mozdulnak! A kutya örökké fogja figyelni azt a békát!'::text),
(326550,36284,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Frosch ist so schnell! Der arme Hund ... ihn jede Sekunde beobachten!'::text,'muss'::text,'muss'::text,'muss nicht'::text,'Der Frosch ist so schnell! Der arme Hund muss ihn jede Sekunde beobachten!'::text),
(326554,36284,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жаба така швидка! Бідолашний пес ... стежити за нею щосекунди!'::text,'має'::text,'мусить'::text,'не має'::text,'Жаба така швидка! Бідолашний пес має стежити за нею щосекунди!'::text),
(326553,36284,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La rana es tan rápida! ¡El pobre perro ... vigilarla cada segundo!'::text,'tiene que'::text,'debe'::text,'no tiene que'::text,'¡La rana es tan rápida! ¡El pobre perro tiene que vigilarla cada segundo!'::text),
(326552,36284,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La grenouille est si rapide ! Le pauvre chien ... la surveiller chaque seconde !'::text,'doit'::text,'doit'::text,'n''a pas besoin de'::text,'La grenouille est si rapide ! Le pauvre chien doit la surveiller chaque seconde !'::text),
(326555,36284,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurbağa çok hızlı! Zavallı köpek onu her saniye ...!'::text,'izlemek zorunda'::text,'izlemeli'::text,'izlemek zorunda değil'::text,'Kurbağa çok hızlı! Zavallı köpek onu her saniye izlemek zorunda!'::text),
(326556,36284,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A béka olyan gyors! Szegény kutyának minden másodpercben ... figyelnie!'::text,'kell'::text,'kell'::text,'nem kell'::text,'A béka olyan gyors! Szegény kutyának minden másodpercben kell figyelnie!'::text),
(294906,32768,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das kleine Flugzeug ... über der Stadt.'::text,'fliegt'::text,'fliegen'::text,'fliegend'::text,'Das kleine Flugzeug fliegt über der Stadt.'::text),
(294910,32768,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленький літак ... над містом.'::text,'летить'::text,'летіти'::text,'летячи'::text,'Маленький літак летить над містом.'::text),
(294909,32768,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La avioneta ... sobre la ciudad.'::text,'vuela'::text,'volar'::text,'volando'::text,'La avioneta vuela sobre la ciudad.'::text),
(294908,32768,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le petit avion ... au-dessus de la ville.'::text,'vole'::text,'voler'::text,'volant'::text,'Le petit avion vole au-dessus de la ville.'::text),
(294911,32768,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük uçak şehrin üzerinde ...'::text,'uçar'::text,'uçmak'::text,'uçarak'::text,'Küçük uçak şehrin üzerinde uçar.'::text),
(294912,32768,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kis repülő a város fölött ...'::text,'repül'::text,'repülni'::text,'repülő'::text,'A kis repülő a város fölött repül.'::text),
(294915,32769,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... auf einem fliegenden Flugzeug stehen.'::text,'kann'::text,'kann'::text,'ist'::text,'Sie kann auf einem fliegenden Flugzeug stehen.'::text),
(294919,32769,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... стояти на літаку в польоті.'::text,'може'::text,'може'::text,'є'::text,'Вона може стояти на літаку в польоті.'::text),
(294918,32769,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... estar de pie sobre un avión en pleno vuelo.'::text,'puede'::text,'puede'::text,'está'::text,'Ella puede estar de pie sobre un avión en pleno vuelo.'::text),
(294917,32769,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... se tenir debout sur un avion en vol.'::text,'peut'::text,'peut'::text,'est'::text,'Elle peut se tenir debout sur un avion en vol.'::text),
(294920,32769,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçan bir uçağın üstünde ayakta ...'::text,'durabilir'::text,'durabilir'::text,NULL::text,'Uçan bir uçağın üstünde ayakta durabilir.'::text),
(294921,32769,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... állni egy éppen repülő gépen.'::text,'tud'::text,'tud'::text,'van'::text,'Ő tud állni egy éppen repülő gépen.'::text),
(294942,32772,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Moment, sie fliegt normalerweise drinnen, aber ich hab gehört, gestern ... sie draußen.'::text,'flog'::text,'fliegt'::text,NULL::text,'Moment, sie fliegt normalerweise drinnen, aber ich hab gehört, gestern flog sie draußen.'::text),
(294946,32772,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стоп, вона зазвичай літає всередині, але я чула, що вчора вона ... зовні.'::text,'летіла'::text,'літає'::text,NULL::text,'Стоп, вона зазвичай літає всередині, але я чула, що вчора вона летіла зовні.'::text),
(294945,32772,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, normalmente vuela dentro, pero me han dicho que ayer ... fuera.'::text,'voló'::text,'vuela'::text,NULL::text,'Espera, normalmente vuela dentro, pero me han dicho que ayer voló fuera.'::text),
(294944,32772,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, d''habitude elle vole à l''intérieur, mais j''ai entendu dire qu''hier elle ... dehors.'::text,'a volé'::text,'vole'::text,NULL::text,'Attends, d''habitude elle vole à l''intérieur, mais j''ai entendu dire qu''hier elle a volé dehors.'::text),
(294947,32772,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, normalde içeride uçar ama duydum ki dün dışarıda ...'::text,'uçtu'::text,'uçar'::text,NULL::text,'Dur, normalde içeride uçar ama duydum ki dün dışarıda uçtu.'::text),
(294948,32772,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, általában bent repül, de azt hallottam, hogy tegnap kint ...'::text,'repült'::text,'repül'::text,NULL::text,'Várj, általában bent repül, de azt hallottam, hogy tegnap kint repült.'::text),
(294951,32773,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also, angeblich ... sie jetzt auf dem Flügel über die Stadt.'::text,'fliegt'::text,'fliegt'::text,'fliegt'::text,'Okay, also, angeblich fliegt sie jetzt auf dem Flügel über die Stadt.'::text),
(294955,32773,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, вона зараз ... над містом на крилі.'::text,'летить'::text,'летить'::text,'летить'::text,'Коротше, кажуть, вона зараз летить над містом на крилі.'::text),
(294954,32773,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer ahora ... sobre la ciudad en el ala.'::text,'está volando'::text,'vuela'::text,'está volando'::text,'Vale, pues al parecer ahora está volando sobre la ciudad en el ala.'::text),
(294953,32773,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment elle ... au-dessus de la ville sur l''aile en ce moment.'::text,'est en train de voler'::text,'vole'::text,'est en train de voler'::text,'Bon alors, apparemment elle est en train de voler au-dessus de la ville sur l''aile en ce moment.'::text),
(294956,32773,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, görünüşe göre şu an kanadın üstünde şehrin üzerinde ...'::text,'uçuyor'::text,'uçar'::text,'uçuyor'::text,'Tamam yani, görünüşe göre şu an kanadın üstünde şehrin üzerinde uçuyor.'::text),
(294957,32773,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag most a szárnyon ... a város fölött.'::text,'repül'::text,'repül'::text,'repül'::text,'Oké, szóval állítólag most a szárnyon repül a város fölött.'::text),
(294960,32774,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise fliegst du drinnen, aber heute ... du auf dem Flügel. Legendär.'::text,'stehst'::text,'stehst'::text,NULL::text,'Normalerweise fliegst du drinnen, aber heute stehst du auf dem Flügel. Legendär.'::text),
(294964,32774,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай ти літаєш усередині, але сьогодні ти ... на крилі. Легендарно.'::text,'стоїш'::text,'стоїш'::text,NULL::text,'Зазвичай ти літаєш усередині, але сьогодні ти стоїш на крилі. Легендарно.'::text),
(294963,32774,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente vuelas dentro, pero hoy ... en el ala. Icónico.'::text,'estás de pie'::text,'estás de pie'::text,NULL::text,'Normalmente vuelas dentro, pero hoy estás de pie en el ala. Icónico.'::text),
(294962,32774,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu voles à l''intérieur, mais aujourd''hui tu ... sur l''aile. Iconique.'::text,'es debout'::text,'es debout'::text,NULL::text,'D''habitude tu voles à l''intérieur, mais aujourd''hui tu es debout sur l''aile. Iconique.'::text),
(294965,32774,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde içeride uçarsın ama bugün kanadın üstünde ..., ikonik.'::text,'duruyorsun'::text,'durursun'::text,NULL::text,'Genelde içeride uçarsın ama bugün kanadın üstünde duruyorsun, ikonik.'::text),
(294966,32774,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában bent repülsz, de ma ... a szárnyon. Ikonikus.'::text,'állsz'::text,'állsz'::text,NULL::text,'Általában bent repülsz, de ma állsz a szárnyon. Ikonikus.'::text),
(294969,32775,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du liebst das Fliegen, ... steigst du raus auf den Flügel. Furchtlos.'::text,'also'::text,'weil'::text,'aber'::text,'Du liebst das Fliegen, also steigst du raus auf den Flügel. Furchtlos.'::text),
(294973,32775,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти обожнюєш літати, ... виходиш на крило. Безстрашно.'::text,'тому'::text,'бо'::text,'але'::text,'Ти обожнюєш літати, тому виходиш на крило. Безстрашно.'::text),
(294972,32775,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te encanta volar, ... sales al ala. Sin miedo.'::text,'así que'::text,'porque'::text,'pero'::text,'Te encanta volar, así que sales al ala. Sin miedo.'::text),
(294971,32775,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu adores voler, ... tu sors sur l''aile. Sans peur.'::text,'donc'::text,'parce que'::text,'mais'::text,'Tu adores voler, donc tu sors sur l''aile. Sans peur.'::text),
(294974,32775,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçmayı seviyorsun, ... kanadın üstüne çıkıyorsun. Korkusuzsun.'::text,'bu yüzden'::text,'çünkü'::text,'ama'::text,'Uçmayı seviyorsun, bu yüzden kanadın üstüne çıkıyorsun. Korkusuzsun.'::text),
(294975,32775,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Imádsz repülni, ... kilépsz a szárnyra. Rettenthetetlen.'::text,'ezért'::text,'mert'::text,'de'::text,'Imádsz repülni, ezért kilépsz a szárnyra. Rettenthetetlen.'::text),
(296076,32898,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie ... jede Menge Zeit für Spaß. Gleich springen sie wieder!'::text,'haben'::text,'hat'::text,'haben'::text,'Alter, sie haben jede Menge Zeit für Spaß. Gleich springen sie wieder!'::text),
(296080,32898,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вони ... купу часу на розваги. Зараз знову стрибнуть!'::text,'мають'::text,'має'::text,'мають'::text,'Бро, вони мають купу часу на розваги. Зараз знову стрибнуть!'::text),
(296079,32898,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ellos ... un montón de tiempo para divertirse. ¡Van a saltar otra vez!'::text,'tienen'::text,'tiene'::text,'tienen'::text,'Tío, ellos tienen un montón de tiempo para divertirse. ¡Van a saltar otra vez!'::text),
(296078,32898,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ils ... plein de temps pour s''amuser. Ils vont encore sauter !'::text,'ont'::text,'a'::text,'ont'::text,'Frérot, ils ont plein de temps pour s''amuser. Ils vont encore sauter !'::text),
(296081,32898,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onların eğlenceye ayıracak bol vakti ..., yine atlayacaklar!'::text,'var'::text,'var'::text,'var'::text,'Kanka, onların eğlenceye ayıracak bol vakti var, yine atlayacaklar!'::text),
(296082,32898,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nekik rengeteg idejük ... a szórakozásra. Mindjárt megint ugranak!'::text,'van'::text,'van'::text,'van'::text,'Tesó, nekik rengeteg idejük van a szórakozásra. Mindjárt megint ugranak!'::text),
(296085,32899,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... haben Spaß auf dem blauen Schlauchboot.'::text,'3 Männer'::text,'3 Mann'::text,'3 Männer'::text,'3 Männer haben Spaß auf dem blauen Schlauchboot.'::text),
(296089,32899,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... розважаються на синьому човні.'::text,'3 чоловіки'::text,'3 чоловік'::text,'3 чоловіки'::text,'3 чоловіки розважаються на синьому човні.'::text),
(296088,32899,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... se lo pasan bien en la lancha azul.'::text,'3 hombres'::text,'3 hombre'::text,'3 hombres'::text,'3 hombres se lo pasan bien en la lancha azul.'::text),
(296087,32899,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... s''amusent sur le canot bleu.'::text,'3 hommes'::text,'3 homme'::text,'3 hommes'::text,'3 hommes s''amusent sur le canot bleu.'::text),
(296090,32899,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mavi botta eğleniyor.'::text,'3 adam'::text,'3 adam'::text,'3 adam'::text,'3 adam mavi botta eğleniyor.'::text),
(296091,32899,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... jól szórakozik a kék gumicsónakon.'::text,'3 férfi'::text,'3 férfi'::text,'3 férfi'::text,'3 férfi jól szórakozik a kék gumicsónakon.'::text),
(296094,32900,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Drei Männer haben Spaß auf einem Schlauchboot. Dann wackelt ... Schlauchboot.'::text,'das'::text,'ein'::text,'ein'::text,'Drei Männer haben Spaß auf einem Schlauchboot. Dann wackelt das Schlauchboot.'::text),
(296098,32900,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Троє чоловіків розважаються на човні. Потім ... човен гойдається.'::text,''::text,NULL::text,NULL::text,'Троє чоловіків розважаються на човні. Потім човен гойдається.'::text),
(296097,32900,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tres hombres se lo pasan bien en una lancha. Luego ... lancha se tambalea.'::text,'la'::text,'una'::text,'una'::text,'Tres hombres se lo pasan bien en una lancha. Luego la lancha se tambalea.'::text),
(296096,32900,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trois hommes s''amusent sur un canot. Puis ... canot tangue.'::text,'le'::text,'un'::text,'un'::text,'Trois hommes s''amusent sur un canot. Puis le canot tangue.'::text),
(296099,32900,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üç adam bir botta eğleniyor. Sonra ... bot sallanıyor.'::text,''::text,'bir'::text,'bir'::text,'Üç adam bir botta eğleniyor. Sonra bot sallanıyor.'::text),
(296100,32900,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Három férfi jól szórakozik egy gumicsónakon. Aztán ... gumicsónak megbillen.'::text,'a'::text,'egy'::text,'egy'::text,'Három férfi jól szórakozik egy gumicsónakon. Aztán a gumicsónak megbillen.'::text),
(296103,32901,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... haben Spaß auf dem Schlauchboot.'::text,'Diese Männer'::text,'Dieser Mann'::text,'Diese Männer'::text,'Diese Männer haben Spaß auf dem Schlauchboot.'::text),
(296107,32901,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... розважаються на човні.'::text,'Ці чоловіки'::text,'Ці чоловіки'::text,'Цей чоловік'::text,'Ці чоловіки розважаються на човні.'::text),
(296106,32901,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... se lo pasan bien en la lancha.'::text,'Estos hombres'::text,'Este hombre'::text,'Estos hombres'::text,'Estos hombres se lo pasan bien en la lancha.'::text),
(296105,32901,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... s''amusent sur le canot.'::text,'Ces hommes'::text,'Cet homme'::text,'Ces hommes'::text,'Ces hommes s''amusent sur le canot.'::text),
(296108,32901,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... botta eğleniyor.'::text,'Bu adamlar'::text,'Bu adamlar'::text,'Bu adam'::text,'Bu adamlar botta eğleniyor.'::text),
(296109,32901,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... jól szórakoznak a gumicsónakon.'::text,'Ezek a férfiak'::text,'Ez a férfi'::text,'Ezek a férfiak'::text,'Ezek a férfiak jól szórakoznak a gumicsónakon.'::text),
(296112,32902,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Von einer Brücke, nur aus Spaß? Ehrlich, ... Style ist krass.'::text,'dein'::text,'du'::text,'deiner'::text,'Von einer Brücke, nur aus Spaß? Ehrlich, dein Style ist krass.'::text),
(296116,32902,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З мосту просто заради розваги? Чесно, ... стиль — це щось.'::text,'твій'::text,'ти'::text,'твій'::text,'З мосту просто заради розваги? Чесно, твій стиль — це щось.'::text),
(296115,32902,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Desde un puente solo por diversión? La verdad, ... estilo es una locura.'::text,'tu'::text,'tú'::text,'tuyo'::text,'¿Desde un puente solo por diversión? La verdad, tu estilo es una locura.'::text),
(296114,32902,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''un pont juste pour le fun ? Franchement, ... style est dingue.'::text,'ton'::text,'toi'::text,'le tien'::text,'D''un pont juste pour le fun ? Franchement, ton style est dingue.'::text),
(296117,32902,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırf eğlence için köprüden mi? Cidden, ... tarzın çılgın.'::text,'senin'::text,'sen'::text,'seninki'::text,'Sırf eğlence için köprüden mi? Cidden, senin tarzın çılgın.'::text),
(296118,32902,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hídról, csak a buli kedvéért? Őszintén, a ... őrült.'::text,'stílusod'::text,'te'::text,'tiéd'::text,'Hídról, csak a buli kedvéért? Őszintén, a stílusod őrült.'::text),
(296121,32903,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du springst ... Sonntagen einfach so aus Spaß von Brücken? Respekt.'::text,'an'::text,'im'::text,'um'::text,'Du springst an Sonntagen einfach so aus Spaß von Brücken? Respekt.'::text),
(296125,32903,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти стрибаєш з мостів ... неділях просто для розваги? Респект.'::text,'по'::text,'у'::text,'о'::text,'Ти стрибаєш з мостів по неділях просто для розваги? Респект.'::text),
(296124,32903,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Saltas de puentes ... los domingos solo por diversión? Respeto.'::text,''::text,'en'::text,'a'::text,'¿Saltas de puentes los domingos solo por diversión? Respeto.'::text),
(296123,32903,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu sautes des ponts ... le dimanche juste pour le fun ? Respect.'::text,''::text,'dans'::text,'à'::text,'Tu sautes des ponts le dimanche juste pour le fun ? Respect.'::text),
(296126,32903,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pazar günleri ... sırf eğlence için köprülerden mi atlıyorsun? Saygılar.'::text,''::text,NULL::text,NULL::text,'Pazar günleri sırf eğlence için köprülerden mi atlıyorsun? Saygılar.'::text),
(296127,32903,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hidakról ugrálsz ... csak a buli kedvéért? Respekt.'::text,'vasárnaponként'::text,'vasárnapban'::text,'vasárnapkor'::text,'Hidakról ugrálsz vasárnaponként csak a buli kedvéért? Respekt.'::text),
(295086,32788,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Alpakas ... dem Mann über den Hof.'::text,'folgen'::text,'folgt'::text,'folgend'::text,'Die Alpakas folgen dem Mann über den Hof.'::text),
(295090,32788,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Альпаки ... за чоловіком через подвір''я.'::text,'йдуть'::text,'йде'::text,'йдучи'::text,'Альпаки йдуть за чоловіком через подвір''я.'::text),
(295089,32788,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las alpacas ... al hombre por el patio.'::text,'siguen'::text,'sigue'::text,'siguiendo'::text,'Las alpacas siguen al hombre por el patio.'::text),
(295088,32788,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les alpagas ... l''homme à travers la cour.'::text,'suivent'::text,'suit'::text,'suivant'::text,'Les alpagas suivent l''homme à travers la cour.'::text),
(295091,32788,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alpakalar avlu boyunca adamı ...'::text,'takip ederler'::text,'takip eder'::text,'takip ederek'::text,'Alpakalar avlu boyunca adamı takip ederler.'::text),
(295092,32788,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alpakák ... a férfit az udvaron át.'::text,'követik'::text,'követi'::text,'követő'::text,'Az alpakák követik a férfit az udvaron át.'::text),
(295104,32790,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... folgt mir? Der ganze Hof! Totales Chaos!'::text,'Wer'::text,'Wo'::text,'Warum'::text,'Wer folgt mir? Der ganze Hof! Totales Chaos!'::text),
(295108,32790,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... йде за мною? Уся ферма! Повний хаос!'::text,'Хто'::text,'Де'::text,'Чому'::text,'Хто йде за мною? Уся ферма! Повний хаос!'::text),
(295107,32790,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... me está siguiendo? ¡Toda la granja! ¡Un caos absoluto!'::text,'Quién'::text,'Dónde'::text,'Por qué'::text,'¿Quién me está siguiendo? ¡Toda la granja! ¡Un caos absoluto!'::text),
(295106,32790,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... me suit ? Toute la ferme ! Le chaos total !'::text,'Qui'::text,'Où'::text,'Pourquoi'::text,'Qui me suit ? Toute la ferme ! Le chaos total !'::text),
(295109,32790,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beni ... takip ediyor? Bütün çiftlik! Tam bir kaos!'::text,'kim'::text,'nerede'::text,'neden'::text,'Beni kim takip ediyor? Bütün çiftlik! Tam bir kaos!'::text),
(295110,32790,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... követ engem? Az egész farm! Totális káosz!'::text,'Ki'::text,'Hol'::text,'Miért'::text,'Ki követ engem? Az egész farm! Totális káosz!'::text),
(295113,32791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Die Alpakas haben entschieden: Sie ... mir für immer folgen!'::text,'werden'::text,'werden'::text,'wird'::text,'Albtraum! Die Alpakas haben entschieden: Sie werden mir für immer folgen!'::text),
(295117,32791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Альпаки вирішили: вони ... ходити за мною вічно!'::text,'збираються'::text,'збираються'::text,'збирається'::text,'Жах! Альпаки вирішили: вони збираються ходити за мною вічно!'::text),
(295116,32791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! Las alpacas lo han decidido: ¡... seguirme para siempre!'::text,'van a'::text,'van a'::text,'va a'::text,'¡Pesadilla! Las alpacas lo han decidido: ¡van a seguirme para siempre!'::text),
(295115,32791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Les alpagas ont décidé : elles ... me suivre pour toujours !'::text,'vont'::text,'vont'::text,'va'::text,'Cauchemar ! Les alpagas ont décidé : elles vont me suivre pour toujours !'::text),
(295118,32791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Alpakalar karar verdi: beni sonsuza dek ...!'::text,'takip edecekler'::text,'takip edecekler'::text,'takip edecek'::text,'Kâbus! Alpakalar karar verdi: beni sonsuza dek takip edecekler!'::text),
(295119,32791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Az alpakák eldöntötték: örökké ... követni engem!'::text,'fognak'::text,'fognak'::text,'fog'::text,'Rémálom! Az alpakák eldöntötték: örökké fognak követni engem!'::text),
(295131,32793,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, das ist eine Hofregel: Die Tiere ... ihm nach draußen folgen.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Hör zu, er hat mir gesagt, das ist eine Hofregel: Die Tiere müssen ihm nach draußen folgen.'::text),
(295135,32793,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він мені сказав, що це правило ферми: тварини ... йти за ним надвір.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Слухай, він мені сказав, що це правило ферми: тварини мають йти за ним надвір.'::text),
(295134,32793,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que es una norma de la granja: los animales ... seguirlo hacia fuera.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Escucha, me dijo que es una norma de la granja: los animales tienen que seguirlo hacia fuera.'::text),
(295133,32793,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que c''est une règle de la ferme : les animaux ... le suivre dehors.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Écoute, il m''a dit que c''est une règle de la ferme : les animaux doivent le suivre dehors.'::text),
(295136,32793,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana bunun bir çiftlik kuralı olduğunu söyledi: hayvanlar onu dışarıya kadar ...'::text,'takip etmek zorunda'::text,'takip etmeli'::text,'takip etmeli'::text,'Dinle, bana bunun bir çiftlik kuralı olduğunu söyledi: hayvanlar onu dışarıya kadar takip etmek zorunda.'::text),
(295137,32793,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy ez farmszabály: az állatoknak ... követniük őt kifelé.'::text,'kell'::text,'kell'::text,'kellene'::text,'Figyelj, azt mondta, hogy ez farmszabály: az állatoknak kell követniük őt kifelé.'::text),
(295140,32794,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, diese Alpakas folgen dir überall hin. Du ... wegrennen, echt jetzt.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Digga, diese Alpakas folgen dir überall hin. Du solltest wegrennen, echt jetzt.'::text),
(295144,32794,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, ті альпаки ходять за тобою всюди. Ти ... тікати, реально.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Чувак, ті альпаки ходять за тобою всюди. Ти мав би тікати, реально.'::text),
(295143,32794,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, esas alpacas te siguen a todas partes. Tú ... salir corriendo, en serio.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'Tío, esas alpacas te siguen a todas partes. Tú deberías salir corriendo, en serio.'::text),
(295142,32794,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ces alpagas te suivent partout. Tu ... courir, sérieux.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Mec, ces alpagas te suivent partout. Tu devrais courir, sérieux.'::text),
(295145,32794,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o alpakalar her yerde peşinde. Sen ..., ciddiyim.'::text,'kaçmalısın'::text,'kaçmalısın'::text,'kaçmalısın'::text,'Kanka, o alpakalar her yerde peşinde. Sen kaçmalısın, ciddiyim.'::text),
(295146,32794,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, azok az alpakák mindenhová követnek. Neked ... futnod, komolyan.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Haver, azok az alpakák mindenhová követnek. Neked kellene futnod, komolyan.'::text),
(295149,32795,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Alter, die Alpakas folgen ihm, ... er das Futter hat, ohne Witz.'::text,'weil'::text,'aber'::text,'also'::text,'Nee Alter, die Alpakas folgen ihm, weil er das Futter hat, ohne Witz.'::text),
(295153,32795,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, альпаки ходять за ним, ... в нього їжа, без жартів.'::text,'бо'::text,'але'::text,'тому'::text,'Не, бро, альпаки ходять за ним, бо в нього їжа, без жартів.'::text),
(295152,32795,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, las alpacas lo siguen ... él tiene la comida, en serio.'::text,'porque'::text,'pero'::text,'así que'::text,'Qué va, tío, las alpacas lo siguen porque él tiene la comida, en serio.'::text),
(295151,32795,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, les alpagas le suivent ... lui, il a la bouffe, sans mentir.'::text,'parce que'::text,'mais'::text,'donc'::text,'Nan frérot, les alpagas le suivent parce que lui, il a la bouffe, sans mentir.'::text),
(295154,32795,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, alpakalar onu takip ediyor ... yem onda, yemin ederim.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Yok kanka, alpakalar onu takip ediyor çünkü yem onda, yemin ederim.'::text),
(295155,32795,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, az alpakák követik, ... nála van a kaja, komolyan.'::text,'mert'::text,'de'::text,'ezért'::text,'Á, tesó, az alpakák követik, mert nála van a kaja, komolyan.'::text),
