(317619,35291,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kikötőben a víz ... nagyon sima.'::text,''::text,NULL::text,'vagyok'::text,'A kikötőben a víz nagyon sima.'::text),
(317622,35292,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... auf ihrem Board über das glatte Wasser.'::text,'gleitet'::text,'gleiten'::text,'gleitend'::text,'Sie gleitet auf ihrem Board über das glatte Wasser.'::text),
(317626,35292,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... гладенькою водою на своїй дошці.'::text,'ковзає'::text,'ковзати'::text,'ковзаючи'::text,'Вона ковзає гладенькою водою на своїй дошці.'::text),
