(317634,35293,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella ... deslizarse porque el agua está superlisa.'::text,'puede'::text,'puede'::text,'está'::text,'Tío, ella puede deslizarse porque el agua está superlisa.'::text),
