(317649,35295,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Q3-Bericht: Dieser Hafen ist ... als das offene Meer.'::text,'glatter'::text,'am glattesten'::text,'glatt'::text,'Q3-Bericht: Dieser Hafen ist glatter als das offene Meer.'::text),
