(317671,35297,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вода гладенька, тож вона ковзає дуже ...'::text,'плавно'::text,'плавний'::text,'плавність'::text,'Вода гладенька, тож вона ковзає дуже плавно.'::text),
