(325056,36118,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, gestern ... sich der Bulldog am Ende um. Legendär.'::text,'drehte'::text,'dreht'::text,'drehend'::text,'Yo, gestern drehte sich der Bulldog am Ende um. Legendär.'::text),
(325060,36118,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, учора бульдог ... в кінці. Легенда.'::text,'розвернувся'::text,'розвертається'::text,'розвертаючись'::text,'Йо, учора бульдог розвернувся в кінці. Легенда.'::text),
