(325058,36118,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, hier, le bouledogue ... à la fin. Iconique.'::text,'a fait demi-tour'::text,'fait demi-tour'::text,'faisant demi-tour'::text,'Yo, hier, le bouledogue a fait demi-tour à la fin. Iconique.'::text),
(325061,36118,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dün buldog yolun sonunda ..., efsane.'::text,'geri döndü'::text,'geri döner'::text,'geri dönerek'::text,'Kanka, dün buldog yolun sonunda geri döndü, efsane.'::text),
(325062,36118,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, tegnap a bulldog ... a végén. Ikonikus.'::text,'megfordult'::text,'megfordul'::text,'megforduló'::text,'Tesó, tegnap a bulldog megfordult a végén. Ikonikus.'::text),
(325065,36119,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI: Der Bulldog ... sich jeden Morgen 3-mal um.'::text,'dreht'::text,'drehte'::text,NULL::text,'KPI: Der Bulldog dreht sich jeden Morgen 3-mal um.'::text),
(325069,36119,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI: бульдог ... 3 рази щоранку.'::text,'розвертається'::text,'розвернувся'::text,NULL::text,'KPI: бульдог розвертається 3 рази щоранку.'::text),
