(325067,36119,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI : le bouledogue ... 3 fois chaque matin.'::text,'fait demi-tour'::text,'a fait demi-tour'::text,NULL::text,'KPI : le bouledogue fait demi-tour 3 fois chaque matin.'::text),
(325070,36119,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI: buldog her sabah 3 kez ...'::text,'geri döner'::text,'geri döndü'::text,NULL::text,'KPI: buldog her sabah 3 kez geri döner.'::text),
(325071,36119,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI: a bulldog minden reggel 3-szor ...'::text,'megfordul'::text,'megfordult'::text,NULL::text,'KPI: a bulldog minden reggel 3-szor megfordul.'::text),
