(325078,36120,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Бульдог ... на своєму скейтборді!'::text,'розвертається'::text,'розвертається'::text,'розвертається'::text,'Жах! Бульдог розвертається на своєму скейтборді!'::text),
(325077,36120,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡El bulldog ... en su monopatín!'::text,'se está dando la vuelta'::text,'se da la vuelta'::text,'se está dando la vuelta'::text,'¡Pesadilla! ¡El bulldog se está dando la vuelta en su monopatín!'::text),
(325076,36120,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Le bouledogue ... sur son skateboard !'::text,'est en train de faire demi-tour'::text,'fait demi-tour'::text,'est en train de faire demi-tour'::text,'Cauchemar ! Le bouledogue est en train de faire demi-tour sur son skateboard !'::text),
(325079,36120,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Buldog kaykayının üstünde ...!'::text,'dönüyor'::text,'döner'::text,'dönüyor'::text,'Kâbus! Buldog kaykayının üstünde dönüyor!'::text),
(325080,36120,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A bulldog ... a gördeszkáján!'::text,'megfordul'::text,'megfordul'::text,'megfordul'::text,'Rémálom! A bulldog megfordul a gördeszkáján!'::text),
(325083,36121,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er fährt immer geradeaus, aber jetzt ... er sich um! Total schockierend!'::text,'dreht'::text,'dreht'::text,NULL::text,'Er fährt immer geradeaus, aber jetzt dreht er sich um! Total schockierend!'::text),
(325087,36121,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він завжди їде прямо, але зараз він ...! Абсолютний шок!'::text,'розвертається'::text,'розвертається'::text,NULL::text,'Він завжди їде прямо, але зараз він розвертається! Абсолютний шок!'::text),
(325086,36121,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Siempre va recto, ¡pero ahora ...! ¡Totalmente impactante!'::text,'se está dando la vuelta'::text,'se da la vuelta'::text,NULL::text,'Siempre va recto, ¡pero ahora se está dando la vuelta! ¡Totalmente impactante!'::text),
(325085,36121,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il roule toujours tout droit, mais là il ... ! Absolument choquant !'::text,'est en train de faire demi-tour'::text,'fait demi-tour'::text,NULL::text,'Il roule toujours tout droit, mais là il est en train de faire demi-tour ! Absolument choquant !'::text),
(325088,36121,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hep dümdüz gider ama şimdi ...! Tamamen şok edici!'::text,'dönüyor'::text,'döner'::text,NULL::text,'Hep dümdüz gider ama şimdi dönüyor! Tamamen şok edici!'::text),
(325089,36121,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindig egyenesen megy, de most ...! Teljesen sokkoló!'::text,'megfordul'::text,'megfordul'::text,NULL::text,'Mindig egyenesen megy, de most megfordul! Teljesen sokkoló!'::text),
(325092,36122,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Straße endet bald, also glaube ich, dass der Hund sich ...'::text,'umdrehen wird'::text,'umdreht'::text,'umdrehte'::text,'Die Straße endet bald, also glaube ich, dass der Hund sich umdrehen wird.'::text),
(325096,36122,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дорога скоро закінчується, тож думаю, що пес ...'::text,'розвернеться'::text,'розвертається'::text,'розвернувся'::text,'Дорога скоро закінчується, тож думаю, що пес розвернеться.'::text),
(325095,36122,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El camino se acaba pronto, así que creo que el perro ...'::text,'se dará la vuelta'::text,'se da la vuelta'::text,'se dio la vuelta'::text,'El camino se acaba pronto, así que creo que el perro se dará la vuelta.'::text),
(325094,36122,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La route se termine bientôt, alors je pense que le chien ...'::text,'fera demi-tour'::text,'fait demi-tour'::text,'a fait demi-tour'::text,'La route se termine bientôt, alors je pense que le chien fera demi-tour.'::text),
(325097,36122,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yol birazdan bitiyor, bu yüzden bence köpek ...'::text,'geri dönecek'::text,'geri döner'::text,'geri döndü'::text,'Yol birazdan bitiyor, bu yüzden bence köpek geri dönecek.'::text),
