(325101,36123,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie haben einen Plan: Der Bulldog ... an der Eiche rechts abbiegen.'::text,'wird'::text,'wird'::text,'abbiegen'::text,'Sie haben einen Plan: Der Bulldog wird an der Eiche rechts abbiegen.'::text),
(325105,36123,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У них план: бульдог ... праворуч біля дуба.'::text,'збирається повернути'::text,'поверне'::text,'повертати'::text,'У них план: бульдог збирається повернути праворуч біля дуба.'::text),
(325104,36123,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tienen un plan: el bulldog ... a la derecha en el roble.'::text,'va a girar'::text,'girará'::text,'girar'::text,'Tienen un plan: el bulldog va a girar a la derecha en el roble.'::text),
(325103,36123,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont un plan : le bouledogue ... à droite au niveau du chêne.'::text,'va tourner'::text,'tournera'::text,'tourner'::text,'Ils ont un plan : le bouledogue va tourner à droite au niveau du chêne.'::text),
