(304306,33812,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він любить свою тачку, але вчора ввечері він ... її більше, реально.'::text,'любив'::text,'любить'::text,NULL::text,'Бро, він любить свою тачку, але вчора ввечері він любив її більше, реально.'::text),
(304305,33812,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ama su coche, pero anoche él ... más a ella, en serio.'::text,'amó'::text,'ama'::text,NULL::text,'Tío, él ama su coche, pero anoche él amó más a ella, en serio.'::text),
(304304,33812,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il aime sa voiture, mais hier soir il ... plus, sérieux.'::text,'l''a aimée'::text,'l''aime'::text,NULL::text,'Frérot, il aime sa voiture, mais hier soir il l''a aimée plus, sérieux.'::text),
(304307,33812,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, arabasını sever ama dün gece onu daha çok ..., cidden.'::text,'sevdi'::text,'sever'::text,NULL::text,'Kanka, arabasını sever ama dün gece onu daha çok sevdi, cidden.'::text),
(304308,33812,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, imádja a kocsiját, de tegnap este őt jobban ..., komolyan.'::text,'szerette'::text,'szereti'::text,NULL::text,'Tesó, imádja a kocsiját, de tegnap este őt jobban szerette, komolyan.'::text),
(304311,33813,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich im Auto an den Händen, weil sie sich lieben.'::text,'halten'::text,'halten'::text,'halten'::text,'Sie halten sich im Auto an den Händen, weil sie sich lieben.'::text),
(304315,33813,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... за руки в машині, бо кохають одне одного.'::text,'тримаються'::text,'тримаються'::text,'тримаються'::text,'Вони тримаються за руки в машині, бо кохають одне одного.'::text),
(304314,33813,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... en el coche porque se quieren.'::text,'se están dando la mano'::text,'se dan la mano'::text,'se están dando la mano'::text,'Ellos se están dando la mano en el coche porque se quieren.'::text),
(304313,33813,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... la main dans la voiture parce qu''ils s''aiment.'::text,'sont en train de se tenir'::text,'se tiennent'::text,'sont en train de se tenir'::text,'Ils sont en train de se tenir la main dans la voiture parce qu''ils s''aiment.'::text),
(304316,33813,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabada el ele ... çünkü birbirlerini seviyorlar.'::text,'tutuşuyorlar'::text,'tutuşurlar'::text,'tutuşuyorlar'::text,'Arabada el ele tutuşuyorlar çünkü birbirlerini seviyorlar.'::text),
(304317,33813,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autóban ... egymás kezét, mert szeretik egymást.'::text,'fogják'::text,'fogják'::text,'fogják'::text,'Az autóban fogják egymás kezét, mert szeretik egymást.'::text),
(304320,33814,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er liebt sie, und gerade ... er im Auto ihre Hand.'::text,'hält'::text,'hält'::text,NULL::text,'Er liebt sie, und gerade hält er im Auto ihre Hand.'::text),
(304324,33814,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він кохає її, і саме зараз він ... її за руку в машині.'::text,'тримає'::text,'тримає'::text,NULL::text,'Він кохає її, і саме зараз він тримає її за руку в машині.'::text),
(304323,33814,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él la quiere, y ahora mismo le ... la mano en el coche.'::text,'está cogiendo'::text,'coge'::text,NULL::text,'Él la quiere, y ahora mismo le está cogiendo la mano en el coche.'::text),
(304322,33814,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il l''aime, et en ce moment il lui ... la main dans la voiture.'::text,'tient'::text,'tient'::text,NULL::text,'Il l''aime, et en ce moment il lui tient la main dans la voiture.'::text),
(304325,33814,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu seviyor ve şu an arabada elini ...'::text,'tutuyor'::text,'tutar'::text,NULL::text,'Onu seviyor ve şu an arabada elini tutuyor.'::text),
(304326,33814,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szereti őt, és most épp ... a kezét az autóban.'::text,'fogja'::text,'fogja'::text,NULL::text,'Szereti őt, és most épp fogja a kezét az autóban.'::text),
(304329,33815,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Starker Move, ihre Hand zu nehmen. Ich glaube, dass sie dich für immer ...'::text,'lieben wird'::text,'liebt'::text,'liebte'::text,'Starker Move, ihre Hand zu nehmen. Ich glaube, dass sie dich für immer lieben wird.'::text),
(304333,33815,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Красивий хід — узяти її за руку. Думаю, вона ... тебе вічно.'::text,'кохатиме'::text,'кохає'::text,'кохала'::text,'Красивий хід — узяти її за руку. Думаю, вона кохатиме тебе вічно.'::text),
(304332,33815,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen movimiento, cogerle la mano. Creo que ella te ... para siempre.'::text,'querrá'::text,'está queriendo'::text,'quiso'::text,'Buen movimiento, cogerle la mano. Creo que ella te querrá para siempre.'::text),
(304331,33815,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Joli coup de lui prendre la main. Je pense qu''elle ... pour toujours.'::text,'t''aimera'::text,'est en train de t''aimer'::text,'t''a aimé'::text,'Joli coup de lui prendre la main. Je pense qu''elle t''aimera pour toujours.'::text),
(304334,33815,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elini tutman çok havalıydı. Bence seni sonsuza dek ...'::text,'sevecek'::text,'seviyor'::text,'sevdi'::text,'Elini tutman çok havalıydı. Bence seni sonsuza dek sevecek.'::text),
(304335,33815,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ügyes húzás megfogni a kezét. Szerintem örökké ... téged.'::text,'szeretni fog'::text,'szeret'::text,'szeretett'::text,'Ügyes húzás megfogni a kezét. Szerintem örökké szeretni fog téged.'::text),
(304338,33816,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Guter Plan, ehrlich: Du ... ihr heute Abend sagen, dass du sie liebst.'::text,'wirst'::text,'wird'::text,'wirst'::text,'Guter Plan, ehrlich: Du wirst ihr heute Abend sagen, dass du sie liebst.'::text),
(304342,33816,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Класний план, чесно: ти ... сказати їй сьогодні ввечері, що кохаєш її.'::text,'збираєшся'::text,'збирається'::text,'збираєшся'::text,'Класний план, чесно: ти збираєшся сказати їй сьогодні ввечері, що кохаєш її.'::text),
(304341,33816,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen plan, la verdad: esta noche ... decirle que la quieres.'::text,'vas a'::text,'va a'::text,'vas a'::text,'Buen plan, la verdad: esta noche vas a decirle que la quieres.'::text),
(304340,33816,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Joli plan, franchement : tu ... lui dire ce soir que tu l''aimes.'::text,'vas'::text,'va'::text,'vas'::text,'Joli plan, franchement : tu vas lui dire ce soir que tu l''aimes.'::text),
(304343,33816,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güzel plan, cidden: bu gece ona onu sevdiğini ...'::text,'söyleyeceksin'::text,'söyleyecek'::text,'söyleyeceksin'::text,'Güzel plan, cidden: bu gece ona onu sevdiğini söyleyeceksin.'::text),
(304344,33816,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jó terv, őszintén: ma este meg ... mondani neki, hogy szereted.'::text,'fogod'::text,'fogja'::text,'fogod'::text,'Jó terv, őszintén: ma este meg fogod mondani neki, hogy szereted.'::text),
(304347,33817,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr subtil, klar. Er verspricht ihr: „Ich ... dich für immer lieben.“'::text,'werde'::text,'werde'::text,NULL::text,'Sehr subtil, klar. Er verspricht ihr: „Ich werde dich für immer lieben.“'::text),
(304351,33817,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже тонко, звісно. Він обіцяє їй: «Я ... кохати тебе вічно».'::text,'буду'::text,'збираюся'::text,NULL::text,'Дуже тонко, звісно. Він обіцяє їй: «Я буду кохати тебе вічно».'::text),
(304350,33817,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy sutil, obviamente. Él le promete: «Te ... para siempre».'::text,'querré'::text,'voy a querer'::text,NULL::text,'Muy sutil, obviamente. Él le promete: «Te querré para siempre».'::text),
(304349,33817,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très subtil, évidemment. Il lui promet : « Je t''... pour toujours. »'::text,'aimerai'::text,'vais aimer'::text,NULL::text,'Très subtil, évidemment. Il lui promet : « Je t''aimerai pour toujours. »'::text),
(304352,33817,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok ince, tabii ki. Ona söz veriyor: “Seni sonsuza dek ...”'::text,'seveceğim'::text,'seveceğim'::text,NULL::text,'Çok ince, tabii ki. Ona söz veriyor: “Seni sonsuza dek seveceğim”'::text),
(304353,33817,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon finom, persze. Megígéri neki: „Örökké szeretni ...”'::text,'foglak'::text,'foglak'::text,NULL::text,'Nagyon finom, persze. Megígéri neki: „Örökké szeretni foglak”'::text),
(304797,33867,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... einen Burger und Pommes als Essen.'::text,'hat'::text,'haben'::text,'hat'::text,'Der Mann hat einen Burger und Pommes als Essen.'::text),
(304801,33867,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... на їжу бургер і картоплю фрі.'::text,'має'::text,'мати'::text,'має'::text,'Чоловік має на їжу бургер і картоплю фрі.'::text),
(304800,33867,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... una hamburguesa y patatas fritas para comer.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'El hombre tiene una hamburguesa y patatas fritas para comer.'::text),
(304799,33867,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... un burger et des frites pour son repas.'::text,'a'::text,'ont'::text,'a'::text,'L''homme a un burger et des frites pour son repas.'::text),
(304802,33867,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamın yemeğinde bir burger ve patates kızartması ...'::text,'var'::text,'var'::text,'var'::text,'Adamın yemeğinde bir burger ve patates kızartması var.'::text),
(304803,33867,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfinak egy burger és sült krumpli ... az étkezéshez.'::text,'van'::text,'van'::text,'van'::text,'A férfinak egy burger és sült krumpli van az étkezéshez.'::text),
(304815,33869,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kellner bringt ... Teller für ihr Essen.'::text,'zwei'::text,'zweiten'::text,'zweimal'::text,'Der Kellner bringt zwei Teller für ihr Essen.'::text),
(304819,33869,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіціант приносить ... тарілки для їхньої їжі.'::text,'дві'::text,'другу'::text,'двічі'::text,'Офіціант приносить дві тарілки для їхньої їжі.'::text),
(304818,33869,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El camarero trae ... platos para su comida.'::text,'dos'::text,'segundo'::text,'dos veces'::text,'El camarero trae dos platos para su comida.'::text),
(304817,33869,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le serveur apporte ... assiettes pour leur repas.'::text,'deux'::text,'deuxième'::text,'deux fois'::text,'Le serveur apporte deux assiettes pour leur repas.'::text),
(304820,33869,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Garson yemekleri için ... tabak getiriyor.'::text,'iki'::text,'ikinci'::text,'iki kez'::text,'Garson yemekleri için iki tabak getiriyor.'::text),
(304821,33869,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pincér ... tányért hoz az étkezésükhöz.'::text,'két'::text,'második'::text,'kétszer'::text,'A pincér két tányért hoz az étkezésükhöz.'::text),
(304824,33870,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine leichte Mahlzeit, klar: so viele ... neben dem Burger.'::text,'Pommes'::text,'Salat'::text,'Brot'::text,'Eine leichte Mahlzeit, klar: so viele Pommes neben dem Burger.'::text),
(304828,33870,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Легка їжа, звісно: стільки ... поруч із бургером.'::text,'картоплі фрі'::text,'салату'::text,'хліба'::text,'Легка їжа, звісно: стільки картоплі фрі поруч із бургером.'::text),
(304827,33870,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una comida ligera, obviamente: tantas ... junto a la hamburguesa.'::text,'patatas fritas'::text,'ensalada'::text,'pan'::text,'Una comida ligera, obviamente: tantas patatas fritas junto a la hamburguesa.'::text),
(304826,33870,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un repas léger, évidemment : tellement de ... à côté du burger.'::text,'frites'::text,'salade'::text,'pain'::text,'Un repas léger, évidemment : tellement de frites à côté du burger.'::text),
(304829,33870,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hafif bir yemek, tabii ki: burgerin yanında bir sürü ...'::text,'patates kızartması'::text,'salata'::text,'ekmek'::text,'Hafif bir yemek, tabii ki: burgerin yanında bir sürü patates kızartması.'::text),
(304830,33870,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Könnyű étkezés, nyilván: annyi ... a burger mellett.'::text,'sült krumpli'::text,'saláta'::text,'kenyér'::text,'Könnyű étkezés, nyilván: annyi sült krumpli a burger mellett.'::text),
(304833,33871,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sein Essen ist legendär, er hat so ... Pommes.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Alter, sein Essen ist legendär, er hat so viele Pommes.'::text),
(304837,33871,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, його їжа — топ, у нього так ... картоплі фрі.'::text,'багато'::text,'багато'::text,'будь-якої'::text,'Бро, його їжа — топ, у нього так багато картоплі фрі.'::text),
(304836,33871,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, su comida es top, tiene ... patatas fritas.'::text,'muchísimas'::text,'muchísima'::text,'cualquier'::text,'Tío, su comida es top, tiene muchísimas patatas fritas.'::text),
(304835,33871,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, son repas est au top, il a ... frites.'::text,'tellement de'::text,'tellement de'::text,'n''importe quelles'::text,'Frérot, son repas est au top, il a tellement de frites.'::text),
(304838,33871,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yemeği efsane, o kadar ... patates kızartması var ki.'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Kanka, yemeği efsane, o kadar çok patates kızartması var ki.'::text),
(304839,33871,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a kajája brutál, annyira ... sült krumplija van.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Tesó, a kajája brutál, annyira sok sült krumplija van.'::text),
(304842,33872,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, da ... zwei Teller, aber das Essen vom Bro ist viel größer.'::text,'sind'::text,'ist'::text,'sein'::text,'Yo, da sind zwei Teller, aber das Essen vom Bro ist viel größer.'::text),
(304846,33872,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, тут ... дві тарілки, але їжа бро набагато більша.'::text,'є'::text,'є'::text,'бути'::text,'Йо, тут є дві тарілки, але їжа бро набагато більша.'::text),
(304845,33872,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... dos platos, pero la comida del colega es mucho más grande.'::text,'hay'::text,'hay'::text,'hay'::text,'Tío, hay dos platos, pero la comida del colega es mucho más grande.'::text),
(304844,33872,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... deux assiettes, mais le repas du gars est bien plus gros.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Yo, il y a deux assiettes, mais le repas du gars est bien plus gros.'::text),
(304847,33872,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, iki tabak ... ama kankanın yemeği çok daha büyük.'::text,'var'::text,'var'::text,'olmak'::text,'Kanka, iki tabak var ama kankanın yemeği çok daha büyük.'::text),
(304848,33872,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, két tányér ..., de a haver kajája sokkal nagyobb.'::text,'van'::text,'van'::text,'lenni'::text,'Tesó, két tányér van, de a haver kajája sokkal nagyobb.'::text),
(304860,33874,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er beißt in den Burger, ... ein Essen zum Essen da ist.'::text,'weil'::text,'aber'::text,'also'::text,'Er beißt in den Burger, weil ein Essen zum Essen da ist.'::text),
(304864,33874,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він кусає бургер, ... їжа для того, щоб її їсти.'::text,'бо'::text,'але'::text,'тому'::text,'Він кусає бургер, бо їжа для того, щоб її їсти.'::text),
(304863,33874,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muerde la hamburguesa ... la comida es para comer.'::text,'porque'::text,'pero'::text,'así que'::text,'Muerde la hamburguesa porque la comida es para comer.'::text),
(304862,33874,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il croque dans le burger ... les repas, c''est fait pour être mangé.'::text,'parce que'::text,'mais'::text,'donc'::text,'Il croque dans le burger parce que les repas, c''est fait pour être mangé.'::text),
(304865,33874,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burgeri ısırıyor ... yemek yemek içindir.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Burgeri ısırıyor çünkü yemek yemek içindir.'::text),
(304866,33874,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beleharap a burgerbe, ... az étel arra való, hogy megegyék.'::text,'mert'::text,'de'::text,'ezért'::text,'Beleharap a burgerbe, mert az étel arra való, hogy megegyék.'::text),
(319989,35555,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, diese Straße hat keine zwei ..., nur einen.'::text,'Läden'::text,'Laden'::text,'Läden'::text,'Alter, diese Straße hat keine zwei Läden, nur einen.'::text),
(319993,35555,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, на цій вулиці нема двох ..., тільки один.'::text,'магазинів'::text,'магазину'::text,'магазинів'::text,'Бро, на цій вулиці нема двох магазинів, тільки один.'::text),
(319992,35555,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, esta calle no tiene dos ..., solo una.'::text,'tiendas'::text,'tienda'::text,'tiendas'::text,'Tío, esta calle no tiene dos tiendas, solo una.'::text),
(319991,35555,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, cette rue a pas deux ..., juste un.'::text,'magasins'::text,'magasin'::text,'magasins'::text,'Frérot, cette rue a pas deux magasins, juste un.'::text),
(319994,35555,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu sokakta iki ... yok, sadece bir tane var.'::text,'dükkân'::text,'dükkân'::text,'dükkân'::text,'Kanka, bu sokakta iki dükkân yok, sadece bir tane var.'::text),
(319995,35555,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ezen az utcán nincs két ..., csak egy.'::text,'bolt'::text,'bolt'::text,'bolt'::text,'Tesó, ezen az utcán nincs két bolt, csak egy.'::text),
(319998,35556,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, das Ding ist kein Haus, das ist ... Laden.'::text,'ein'::text,'der'::text,'ein'::text,'Alter, das Ding ist kein Haus, das ist ein Laden.'::text),
(320002,35556,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, це місце не будинок, це ... магазин.'::text,''::text,NULL::text,NULL::text,'Бро, це місце не будинок, це магазин.'::text),
(320001,35556,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ese sitio no es una casa, es ... tienda.'::text,'una'::text,'la'::text,'una'::text,'Tío, ese sitio no es una casa, es una tienda.'::text),
(320000,35556,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, cet endroit, c''est pas une maison, c''est ... magasin.'::text,'un'::text,'le'::text,'un'::text,'Frérot, cet endroit, c''est pas une maison, c''est un magasin.'::text),
(320003,35556,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, orası ev değil, ... dükkân.'::text,'bir'::text,NULL::text,'bir'::text,'Kanka, orası ev değil, bir dükkân.'::text),
(320004,35556,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a hely nem ház, hanem ... bolt.'::text,'egy'::text,'a'::text,'egy'::text,'Tesó, az a hely nem ház, hanem egy bolt.'::text),
(320007,35557,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Laden hat ein Ziel von 500 Kokosnüssen.'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Dieser Laden hat ein Ziel von 500 Kokosnüssen.'::text),
(320011,35557,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... магазин має ціль — 500 кокосів.'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей магазин має ціль — 500 кокосів.'::text),
(320010,35557,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tienda tiene un objetivo de 500 cocos.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta tienda tiene un objetivo de 500 cocos.'::text),
(320009,35557,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... magasin a un objectif de 500 noix de coco.'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Ce magasin a un objectif de 500 noix de coco.'::text),
(320012,35557,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dükkânın 500 hindistancevizi hedefi var.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu dükkânın 500 hindistancevizi hedefi var.'::text),
(320013,35557,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a boltnak 500 kókuszdió a célja.'::text,'Ennek'::text,'Ezeknek'::text,'Azoknak'::text,'Ennek a boltnak 500 kókuszdió a célja.'::text),
(320025,35559,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Er sagt Nein ... dem Laden!'::text,'vor'::text,'auf'::text,'an'::text,'Albtraum! Er sagt Nein vor dem Laden!'::text),
(320029,35559,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Він каже «ні» ... магазином!'::text,'перед'::text,'на'::text,'біля'::text,'Жах! Він каже «ні» перед магазином!'::text),
(320028,35559,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Él dice que no ... la tienda!'::text,'delante de'::text,'sobre'::text,'a'::text,'¡Pesadilla! ¡Él dice que no delante de la tienda!'::text),
(320027,35559,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Il dit non ... magasin !'::text,'devant le'::text,'sur le'::text,'au'::text,'Cauchemar ! Il dit non devant le magasin !'::text),
(320030,35559,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Dükkânın ... hayır diyor!'::text,'önünde'::text,'üstünde'::text,NULL::text,'Kâbus! Dükkânın önünde hayır diyor!'::text),
(320031,35559,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Nemet mond a ...!'::text,'bolt előtt'::text,'bolton'::text,'boltnál'::text,'Rémálom! Nemet mond a bolt előtt!'::text),
(320034,35560,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Der Laden hat fünfzig Kokosnüsse, aber sie bekommt nur ...!'::text,'eine'::text,'die erste'::text,'einmal'::text,'Katastrophe! Der Laden hat fünfzig Kokosnüsse, aber sie bekommt nur eine!'::text),
(320038,35560,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Магазин має п''ятдесят кокосів, а вона отримує лише ...!'::text,'один'::text,'перший'::text,'раз'::text,'Катастрофа! Магазин має п''ятдесят кокосів, а вона отримує лише один!'::text),
(320037,35560,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡La tienda tiene cincuenta cocos, pero ella solo consigue ...!'::text,'uno'::text,'el primero'::text,'una vez'::text,'¡Desastre! ¡La tienda tiene cincuenta cocos, pero ella solo consigue uno!'::text),
(320036,35560,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Le magasin a cinquante noix de coco, mais elle en reçoit seulement ... !'::text,'une'::text,'la première'::text,'une fois'::text,'Catastrophe ! Le magasin a cinquante noix de coco, mais elle en reçoit seulement une !'::text),
(320039,35560,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Dükkânda elli hindistancevizi var ama o sadece ... alıyor!'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Felaket! Dükkânda elli hindistancevizi var ama o sadece bir alıyor!'::text),
(320040,35560,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A boltnak ötven kókuszdiója van, de ő csak ... kap!'::text,'egyet'::text,'az elsőt'::text,'egyszer'::text,'Katasztrófa! A boltnak ötven kókuszdiója van, de ő csak egyet kap!'::text),
(320043,35561,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise kauft sie im Laden ein, aber jetzt ... sie draußen.'::text,'steht'::text,'steht'::text,NULL::text,'Normalerweise kauft sie im Laden ein, aber jetzt steht sie draußen.'::text),
(320047,35561,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона купує в магазині, але зараз вона ... надворі.'::text,'стоїть'::text,'стоїть'::text,NULL::text,'Зазвичай вона купує в магазині, але зараз вона стоїть надворі.'::text),
(320046,35561,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente compra en la tienda, pero ahora ... fuera.'::text,'está de pie'::text,'está de pie'::text,NULL::text,'Normalmente compra en la tienda, pero ahora está de pie fuera.'::text),
(320045,35561,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, elle fait ses courses dans le magasin, mais maintenant elle ... dehors.'::text,'est debout'::text,'est debout'::text,NULL::text,'D''habitude, elle fait ses courses dans le magasin, mais maintenant elle est debout dehors.'::text),
(320048,35561,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde dükkândan alışveriş yapar ama şu an dışarıda ...'::text,'duruyor'::text,'durur'::text,NULL::text,'Genelde dükkândan alışveriş yapar ama şu an dışarıda duruyor.'::text),
(320049,35561,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában a boltban vásárol, de most kint ...'::text,'áll'::text,'áll'::text,NULL::text,'Általában a boltban vásárol, de most kint áll.'::text),
(310692,34522,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jeden Abend Golf! Wirklich jeden Abend!'::text,'trainiert'::text,'trainieren'::text,'trainierend'::text,'Sie trainiert jeden Abend Golf! Wirklich jeden Abend!'::text),
(310696,34522,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... гольф щовечора! Абсолютно щовечора!'::text,'тренує'::text,'тренувати'::text,'тренуючи'::text,'Вона тренує гольф щовечора! Абсолютно щовечора!'::text),
(310695,34522,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... golf todas las noches! ¡Absolutamente todas las noches!'::text,'practica'::text,'practicar'::text,'practicando'::text,'¡Ella practica golf todas las noches! ¡Absolutamente todas las noches!'::text),
(310694,34522,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... au golf tous les soirs ! Absolument tous les soirs !'::text,'s''entraîne'::text,'s''entraîner'::text,'s''entraînant'::text,'Elle s''entraîne au golf tous les soirs ! Absolument tous les soirs !'::text),
(310697,34522,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geceleri golf ...! İstisnasız, tek bir gece bile atlamadan!'::text,'çalışır'::text,'çalışmak'::text,'çalışarak'::text,'Geceleri golf çalışır! İstisnasız, tek bir gece bile atlamadan!'::text),
(310698,34522,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden este ... golfot! Tényleg minden este!'::text,'gyakorol'::text,'gyakorolni'::text,'gyakorló'::text,'Minden este gyakorol golfot! Tényleg minden este!'::text),
(310710,34524,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... trainiert sie nachts?! Der Tag ist eine Katastrophe!'::text,'Warum'::text,'Wer'::text,'Wessen'::text,'Warum trainiert sie nachts?! Der Tag ist eine Katastrophe!'::text),
(310714,34524,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона тренується вночі?! Вдень — катастрофа!'::text,'Чому'::text,'Хто'::text,'Чий'::text,'Чому вона тренується вночі?! Вдень — катастрофа!'::text),
(310713,34524,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... practica de noche?! ¡El día es un desastre!'::text,'Por qué'::text,'Quién'::text,'De quién'::text,'¿Por qué practica de noche?! ¡El día es un desastre!'::text),
(310712,34524,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... s''entraîne-t-elle la nuit ?! La journée est une catastrophe !'::text,'Pourquoi'::text,'Qui'::text,'À qui'::text,'Pourquoi s''entraîne-t-elle la nuit ?! La journée est une catastrophe !'::text),
(310715,34524,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... gece antrenman yapıyor?! Gündüz tam bir felaket!'::text,'Neden'::text,'Kim'::text,'Kimin'::text,'Neden gece antrenman yapıyor?! Gündüz tam bir felaket!'::text),
(310716,34524,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... gyakorol éjjel?! A nappal egy katasztrófa!'::text,'Miért'::text,'Ki'::text,'Kinek a'::text,'Miért gyakorol éjjel?! A nappal egy katasztrófa!'::text),
(310728,34526,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie trainiert jede Woche Golf, und gestern Abend ... sie auch hier.'::text,'trainierte'::text,'trainiert'::text,NULL::text,'Sie trainiert jede Woche Golf, und gestern Abend trainierte sie auch hier.'::text),
(310732,34526,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона щотижня тренується в гольф, і вчора ввечері вона теж ... тут.'::text,'тренувалася'::text,'тренується'::text,NULL::text,'Вона щотижня тренується в гольф, і вчора ввечері вона теж тренувалася тут.'::text),
(310731,34526,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Practica golf cada semana, y anoche también ... aquí.'::text,'practicó'::text,'practica'::text,NULL::text,'Practica golf cada semana, y anoche también practicó aquí.'::text),
(310730,34526,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle s''entraîne au golf chaque semaine, et hier soir elle ... ici aussi.'::text,'s''est entraînée'::text,'s''entraîne'::text,NULL::text,'Elle s''entraîne au golf chaque semaine, et hier soir elle s''est entraînée ici aussi.'::text),
(310733,34526,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her hafta golf çalışır ve dün gece de burada ...'::text,'çalıştı'::text,'çalışır'::text,NULL::text,'Her hafta golf çalışır ve dün gece de burada çalıştı.'::text),
(310734,34526,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden héten golfot gyakorol, és tegnap este is itt ...'::text,'gyakorolt'::text,'gyakorol'::text,NULL::text,'Minden héten golfot gyakorol, és tegnap este is itt gyakorolt.'::text),
(310737,34527,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... sie ihren Schwung auf der grünen Matte.'::text,'trainiert'::text,'trainiert'::text,'trainiert'::text,'Gerade trainiert sie ihren Schwung auf der grünen Matte.'::text),
(310741,34527,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз вона ... свій замах на зеленому килимку.'::text,'відпрацьовує'::text,'відпрацьовує'::text,'відпрацьовує'::text,'Саме зараз вона відпрацьовує свій замах на зеленому килимку.'::text),
(310740,34527,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ella ... su swing en la alfombrilla verde.'::text,'está practicando'::text,'practica'::text,'está practicando'::text,'Ahora mismo ella está practicando su swing en la alfombrilla verde.'::text),
(310739,34527,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, elle ... son swing sur le tapis vert.'::text,'est en train de travailler'::text,'travaille'::text,'est en train de travailler'::text,'En ce moment, elle est en train de travailler son swing sur le tapis vert.'::text),
(310742,34527,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an yeşil minderde vuruşunu ...'::text,'çalışıyor'::text,'çalışır'::text,'çalışıyor'::text,'Şu an yeşil minderde vuruşunu çalışıyor.'::text),
(310743,34527,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most épp ... a lendítését a zöld szőnyegen.'::text,'gyakorolja'::text,'gyakorolja'::text,'gyakorolja'::text,'Most épp gyakorolja a lendítését a zöld szőnyegen.'::text),
(310746,34528,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziel: 100 Bälle. Sie trainiert wöchentlich, aber heute ... sie nachts.'::text,'trainiert'::text,'trainiert'::text,NULL::text,'Ziel: 100 Bälle. Sie trainiert wöchentlich, aber heute trainiert sie nachts.'::text),
(310750,34528,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціль: 100 м''ячів. Вона тренується щотижня, але сьогодні вона ... вночі.'::text,'тренується'::text,'тренується'::text,NULL::text,'Ціль: 100 м''ячів. Вона тренується щотижня, але сьогодні вона тренується вночі.'::text),
(310749,34528,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo: 100 bolas. Practica cada semana, pero hoy ... de noche.'::text,'está practicando'::text,'practica'::text,NULL::text,'Objetivo: 100 bolas. Practica cada semana, pero hoy está practicando de noche.'::text),
(310748,34528,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif : 100 balles. Elle s''entraîne chaque semaine, mais aujourd''hui elle ... de nuit.'::text,'est en train de s''entraîner'::text,'s''entraîne'::text,NULL::text,'Objectif : 100 balles. Elle s''entraîne chaque semaine, mais aujourd''hui elle est en train de s''entraîner de nuit.'::text),
(310751,34528,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedef: 100 top. Haftalık çalışır ama bugün gece ...'::text,'çalışıyor'::text,'çalışır'::text,NULL::text,'Hedef: 100 top. Haftalık çalışır ama bugün gece çalışıyor.'::text),
(310752,34528,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cél: 100 labda. Hetente gyakorol, de ma éjjel ...'::text,'gyakorol'::text,'gyakorol'::text,NULL::text,'Cél: 100 labda. Hetente gyakorol, de ma éjjel gyakorol.'::text),
(310755,34529,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie trainiert heute Golf, also ... sie morgen ein Golfstar.'::text,'wird'::text,'ist'::text,'war'::text,'Sie trainiert heute Golf, also wird sie morgen ein Golfstar.'::text),
(310759,34529,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сьогодні тренується в гольф, тож завтра вона ... зіркою гольфу.'::text,'буде'::text,'є'::text,'була'::text,'Вона сьогодні тренується в гольф, тож завтра вона буде зіркою гольфу.'::text),
(310758,34529,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy practica golf, así que mañana ... una estrella del golf.'::text,'será'::text,'es'::text,'fue'::text,'Hoy practica golf, así que mañana será una estrella del golf.'::text),
(310757,34529,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle s''entraîne au golf aujourd''hui, donc demain elle ... une star du golf.'::text,'sera'::text,'est'::text,'était'::text,'Elle s''entraîne au golf aujourd''hui, donc demain elle sera une star du golf.'::text),
(310760,34529,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün golf çalışıyor, bu yüzden yarın bir golf yıldızı ...'::text,'olacak'::text,NULL::text,'idi'::text,'Bugün golf çalışıyor, bu yüzden yarın bir golf yıldızı olacak.'::text),
(310761,34529,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma golfot gyakorol, ezért holnap golfsztár ...'::text,'lesz'::text,NULL::text,'volt'::text,'Ma golfot gyakorol, ezért holnap golfsztár lesz.'::text),
(294501,32723,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Er ... sein Handy in diesem Haus nie!'::text,'findet'::text,'finden'::text,'findend'::text,'Katastrophe! Er findet sein Handy in diesem Haus nie!'::text),
(294505,32723,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Він ніколи не ... свій телефон у цьому домі!'::text,'знаходить'::text,'знаходити'::text,'знаходячи'::text,'Катастрофа! Він ніколи не знаходить свій телефон у цьому домі!'::text),
(294504,32723,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Él nunca ... su móvil en esta casa!'::text,'encuentra'::text,'encontrar'::text,'encontrando'::text,'¡Desastre! ¡Él nunca encuentra su móvil en esta casa!'::text),
(294503,32723,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Il ne ... jamais son téléphone dans cette maison !'::text,'trouve'::text,'trouver'::text,'trouvant'::text,'Catastrophe ! Il ne trouve jamais son téléphone dans cette maison !'::text),
(294506,32723,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Bu evde telefonunu hiçbir zaman ...!'::text,'bulmaz'::text,'bulmamak'::text,'bulmayarak'::text,'Felaket! Bu evde telefonunu hiçbir zaman bulmaz!'::text),
(294507,32723,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Soha nem ... a telefonját ebben a házban!'::text,'találja'::text,'találni'::text,'találó'::text,'Katasztrófa! Soha nem találja a telefonját ebben a házban!'::text),
