(294514,32724,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не ... знайти свій телефон на дивані.'::text,'може'::text,'може'::text,'є'::text,'Він не може знайти свій телефон на дивані.'::text),
(294513,32724,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él no ... encontrar su móvil en el sofá.'::text,'puede'::text,'puede'::text,'está'::text,'Él no puede encontrar su móvil en el sofá.'::text),
