(294515,32724,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefonunu kanepede ...'::text,'bulamaz'::text,'bulamaz'::text,NULL::text,'Telefonunu kanepede bulamaz.'::text),
(294516,32724,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ... megtalálni a telefonját a kanapén.'::text,'tudja'::text,'tudja'::text,'van'::text,'Nem tudja megtalálni a telefonját a kanapén.'::text),
