(294548,32728,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... trouver son téléphone parce qu''il n''est pas dans sa main.'::text,'doit'::text,'doit'::text,'devrait'::text,'Il doit trouver son téléphone parce qu''il n''est pas dans sa main.'::text),
(294551,32728,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefonunu ... çünkü elinde değil.'::text,'bulmak zorunda'::text,'bulmalı'::text,'bulmalı'::text,'Telefonunu bulmak zorunda çünkü elinde değil.'::text),
