(294555,32729,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Handy ist für immer weg! Er ... es finden, bevor er alles verliert!'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Das Handy ist für immer weg! Er sollte es finden, bevor er alles verliert!'::text),
(294559,32729,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Телефон зник назавжди! Він ... знайти його, поки не втратив усе!'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Телефон зник назавжди! Він мав би знайти його, поки не втратив усе!'::text),
