(304081,33787,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... — це один важкий вантаж.'::text,'Ці лежаки'::text,'Ці лежаки'::text,'Цей лежак'::text,'Ці лежаки — це один важкий вантаж.'::text),
(304080,33787,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... son una carga pesada.'::text,'Estas tumbonas'::text,'Esta tumbona'::text,'Estas tumbonas'::text,'Estas tumbonas son una carga pesada.'::text),
(304079,33787,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sont une lourde charge.'::text,'Ces transats'::text,'Ce transat'::text,'Ces transats'::text,'Ces transats sont une lourde charge.'::text),
(304082,33787,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tek bir ağır yük.'::text,'Bu şezlonglar'::text,'Bu şezlonglar'::text,'Bu şezlong'::text,'Bu şezlonglar tek bir ağır yük.'::text),
(304083,33787,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... egyetlen nehéz teher.'::text,'Ezek a nyugágyak'::text,'Ez a nyugágy'::text,'Ezek a nyugágyak'::text,'Ezek a nyugágyak egyetlen nehéz teher.'::text),
(304095,33789,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er trägt die riesige Last ... Mittag! Echt furchtbar!'::text,'am'::text,'am'::text,'im'::text,'Er trägt die riesige Last am Mittag! Echt furchtbar!'::text),
(304099,33789,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він несе величезний вантаж ... полудні! Просто жах!'::text,'о'::text,'на'::text,'у'::text,'Він несе величезний вантаж о полудні! Просто жах!'::text),
(304098,33789,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Lleva la carga enorme ... mediodía! ¡Horrible!'::text,'al'::text,'sobre el'::text,'en el'::text,'¡Lleva la carga enorme al mediodía! ¡Horrible!'::text),
(304097,33789,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il porte l''énorme charge ... midi ! Absolument horrible !'::text,'à'::text,'sur'::text,'dans'::text,'Il porte l''énorme charge à midi ! Absolument horrible !'::text),
(304100,33789,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devasa yükü öğlen ... taşıyor! Tamamen korkunç!'::text,''::text,NULL::text,NULL::text,'Devasa yükü öğlen taşıyor! Tamamen korkunç!'::text),
(304101,33789,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cipeli a hatalmas terhet! Borzalmas!'::text,'Délben'::text,'Délen'::text,'Délben'::text,'Délben cipeli a hatalmas terhet! Borzalmas!'::text),
(304104,33790,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat ... Stapel in seiner Ladung.'::text,'zwei'::text,'zweiten'::text,'Zweien'::text,'Er hat zwei Stapel in seiner Ladung.'::text),
(304108,33790,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він має ... стоси у своєму вантажі.'::text,'два'::text,'другий'::text,'двійки'::text,'Він має два стоси у своєму вантажі.'::text),
(304107,33790,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él tiene ... pilas en su carga.'::text,'dos'::text,'segunda'::text,'dos'::text,'Él tiene dos pilas en su carga.'::text),
(304106,33790,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a ... piles dans sa charge.'::text,'deux'::text,'deuxième'::text,'deux'::text,'Il a deux piles dans sa charge.'::text),
(304109,33790,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yükünde ... yığın var.'::text,'iki'::text,'ikinci'::text,'ikiler'::text,'Yükünde iki yığın var.'::text),
(304110,33790,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A terhében ... halom van.'::text,'két'::text,'második'::text,'kettesek'::text,'A terhében két halom van.'::text),
(295671,32853,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Echt jetzt, angeblich ... gestern Abend vier Freunde ums Feuer.'::text,'saßen'::text,'sitzen'::text,'saßen'::text,'Echt jetzt, angeblich saßen gestern Abend vier Freunde ums Feuer.'::text),
(295675,32853,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, кажуть, учора ввечері четверо друзів ... біля вогнища.'::text,'сиділи'::text,'сидять'::text,'сиділи'::text,'Та ну, кажуть, учора ввечері четверо друзів сиділи біля вогнища.'::text),
(295674,32853,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede ser, dicen que anoche cuatro amigos ... alrededor del fuego.'::text,'se sentaron'::text,'se sientan'::text,'se sentaron'::text,'No puede ser, dicen que anoche cuatro amigos se sentaron alrededor del fuego.'::text),
(295673,32853,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sérieux, il paraît que quatre amis ... autour du feu hier soir.'::text,'se sont assis'::text,'s''assoient'::text,'se sont assis'::text,'Sérieux, il paraît que quatre amis se sont assis autour du feu hier soir.'::text),
(295676,32853,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok artık, söylentiye göre dün gece dört arkadaş ateşin etrafında ...'::text,'oturdu'::text,'otururlar'::text,'oturdu'::text,'Yok artık, söylentiye göre dün gece dört arkadaş ateşin etrafında oturdu.'::text),
(295677,32853,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hiszem el, állítólag tegnap este négy barát ... a tűz körül.'::text,'ült'::text,'ülnek'::text,'ült'::text,'Nem hiszem el, állítólag tegnap este négy barát ült a tűz körül.'::text),
(295680,32854,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich fahren die Freunde normalerweise, aber gestern ... sie am Strand.'::text,'blieben'::text,'bleiben'::text,NULL::text,'Mädel, angeblich fahren die Freunde normalerweise, aber gestern blieben sie am Strand.'::text),
(295684,32854,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, друзі зазвичай їздять, але вчора вони ... на пляжі.'::text,'залишилися'::text,'залишаються'::text,NULL::text,'Подруго, кажуть, друзі зазвичай їздять, але вчора вони залишилися на пляжі.'::text),
(295683,32854,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer los amigos normalmente conducen, pero ayer ... en la playa.'::text,'se quedaron'::text,'se quedan'::text,NULL::text,'Tía, al parecer los amigos normalmente conducen, pero ayer se quedaron en la playa.'::text),
(295682,32854,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment les amis roulent d''habitude, mais hier ils ... à la plage.'::text,'sont restés'::text,'restent'::text,NULL::text,'Ma belle, apparemment les amis roulent d''habitude, mais hier ils sont restés à la plage.'::text),
(295685,32854,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, görünüşe göre arkadaşlar genelde yola devam eder ama dün plajda ...'::text,'kaldılar'::text,'kalırlar'::text,NULL::text,'Kızım, görünüşe göre arkadaşlar genelde yola devam eder ama dün plajda kaldılar.'::text),
(295686,32854,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a barátok általában vezetnek, de tegnap a strandon ...'::text,'maradtak'::text,'maradnak'::text,NULL::text,'Csajszi, állítólag a barátok általában vezetnek, de tegnap a strandon maradtak.'::text),
(295689,32855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Du und deine Freunde ... gerade den besten Sonnenuntergang.'::text,'seht'::text,'seht'::text,'sieht'::text,'Respekt: Du und deine Freunde seht gerade den besten Sonnenuntergang.'::text),
(295693,32855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: ти і твої друзі саме зараз ... на найкращий захід сонця.'::text,'дивитеся'::text,'дивитеся'::text,'дивиться'::text,'Респект: ти і твої друзі саме зараз дивитеся на найкращий захід сонця.'::text),
(295692,32855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: tú y tus amigos ... el mejor atardecer ahora mismo.'::text,'estáis viendo'::text,'veis'::text,'está viendo'::text,'Respeto: tú y tus amigos estáis viendo el mejor atardecer ahora mismo.'::text),
(295691,32855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : tes amis et toi, vous ... le plus beau coucher de soleil en ce moment.'::text,'êtes en train de regarder'::text,'regardez'::text,'est en train de regarder'::text,'Respect : tes amis et toi, vous êtes en train de regarder le plus beau coucher de soleil en ce moment.'::text),
(295694,32855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygı: sen ve arkadaşların şu an en güzel gün batımını ...'::text,'izliyorsunuz'::text,'izlersiniz'::text,'izliyor'::text,'Saygı: sen ve arkadaşların şu an en güzel gün batımını izliyorsunuz.'::text),
(295695,32855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: te és a barátaid most ... a legszebb naplementét.'::text,'nézitek'::text,'nézitek'::text,'nézi'::text,'Respekt: te és a barátaid most nézitek a legszebb naplementét.'::text),
(295698,32856,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise fährst du, aber heute Abend ... du mit Freunden da. Legendär.'::text,'sitzt'::text,'sitzt'::text,NULL::text,'Normalerweise fährst du, aber heute Abend sitzt du mit Freunden da. Legendär.'::text),
(295702,32856,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай ти за кермом, але сьогодні ввечері ти ... з друзями. Легендарно.'::text,'сидиш'::text,'сидиш'::text,NULL::text,'Зазвичай ти за кермом, але сьогодні ввечері ти сидиш з друзями. Легендарно.'::text),
(295701,32856,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente conduces tú, pero esta noche ... con tus amigos. Icónico.'::text,'estás sentado'::text,'estás sentado'::text,NULL::text,'Normalmente conduces tú, pero esta noche estás sentado con tus amigos. Icónico.'::text),
(295700,32856,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu conduis, mais ce soir tu ... avec tes amis. Iconique.'::text,'es assis'::text,'es assis'::text,NULL::text,'D''habitude tu conduis, mais ce soir tu es assis avec tes amis. Iconique.'::text),
(295703,32856,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde sen sürersin ama bu akşam arkadaşlarınla ..., ikonik.'::text,'oturuyorsun'::text,'oturursun'::text,NULL::text,'Genelde sen sürersin ama bu akşam arkadaşlarınla oturuyorsun, ikonik.'::text),
(295704,32856,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában te vezetsz, de ma este ... a barátaiddal. Ikonikus.'::text,'ülsz'::text,'ülsz'::text,NULL::text,'Általában te vezetsz, de ma este ülsz a barátaiddal. Ikonikus.'::text),
(295707,32857,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein kleiner Van für vier Freunde? Klar, dass sie Freunde ...'::text,'bleiben werden'::text,'bleiben'::text,'blieben'::text,'Ein kleiner Van für vier Freunde? Klar, dass sie Freunde bleiben werden.'::text),
(295711,32857,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один маленький фургон на чотирьох друзів? Вони ... друзями, звісно.'::text,'залишаться'::text,'залишаються'::text,'залишилися'::text,'Один маленький фургон на чотирьох друзів? Вони залишаться друзями, звісно.'::text),
(295710,32857,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Una furgoneta pequeña para cuatro amigos? ... amigos, obviamente.'::text,'Seguirán siendo'::text,'Siguen siendo'::text,'Siguieron siendo'::text,'¿Una furgoneta pequeña para cuatro amigos? Seguirán siendo amigos, obviamente.'::text),
(295709,32857,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un petit van pour quatre amis ? Ils ... amis, évidemment.'::text,'resteront'::text,'restent'::text,'sont restés'::text,'Un petit van pour quatre amis ? Ils resteront amis, évidemment.'::text),
(295712,32857,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dört arkadaşa küçücük bir minibüs mü? Arkadaş ..., tabii ki.'::text,'kalacaklar'::text,'kalırlar'::text,'kaldılar'::text,'Dört arkadaşa küçücük bir minibüs mü? Arkadaş kalacaklar, tabii ki.'::text),
(295713,32857,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy kis furgon négy barátnak? Barátok ..., nyilván.'::text,'maradni fognak'::text,'maradnak'::text,'maradtak'::text,'Egy kis furgon négy barátnak? Barátok maradni fognak, nyilván.'::text),
(295725,32859,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund sieht verfroren aus, also sagt ein Freund: „Ich ... eine Decke holen.“'::text,'werde'::text,'werde'::text,NULL::text,'Der Hund sieht verfroren aus, also sagt ein Freund: „Ich werde eine Decke holen.“'::text),
(295729,32859,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Схоже, псові холодно, тож друг каже: «Я ... принести ковдру».'::text,'буду'::text,'збираюся'::text,NULL::text,'Схоже, псові холодно, тож друг каже: «Я буду принести ковдру».'::text),
(295728,32859,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro parece tener frío, así que un amigo dice: «... una manta».'::text,'Traeré'::text,'Voy a traer'::text,NULL::text,'El perro parece tener frío, así que un amigo dice: «Traeré una manta».'::text),
(295727,32859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien a l''air d''avoir froid, alors un ami dit : « Je ... une couverture. »'::text,'ramènerai'::text,'vais ramener'::text,NULL::text,'Le chien a l''air d''avoir froid, alors un ami dit : « Je ramènerai une couverture. »'::text),
(295730,32859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek üşümüş görünüyor, bu yüzden bir arkadaş “Bir battaniye ...” diyor.'::text,'getireceğim'::text,'getireceğim'::text,NULL::text,'Köpek üşümüş görünüyor, bu yüzden bir arkadaş “Bir battaniye getireceğim” diyor.'::text),
(295731,32859,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya fázósnak tűnik, ezért egy barát azt mondja: „Hozni ... egy takarót.”'::text,'fogok'::text,'fogok'::text,NULL::text,'A kutya fázósnak tűnik, ezért egy barát azt mondja: „Hozni fogok egy takarót.”'::text),
(295734,32860,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Freunde haben im kleinen Van nicht viel ...'::text,'Platz'::text,'Platz'::text,'einen Platz'::text,'Die Freunde haben im kleinen Van nicht viel Platz.'::text),
(295738,32860,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У друзів немає багато ... в маленькому фургоні.'::text,'місця'::text,'місць'::text,'місця'::text,'У друзів немає багато місця в маленькому фургоні.'::text),
(295737,32860,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los amigos no tienen mucho ... en la furgoneta pequeña.'::text,'espacio'::text,'espacio'::text,'un espacio'::text,'Los amigos no tienen mucho espacio en la furgoneta pequeña.'::text),
(295736,32860,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les amis n''ont pas beaucoup de ... dans le petit van.'::text,'place'::text,'place'::text,'une place'::text,'Les amis n''ont pas beaucoup de place dans le petit van.'::text),
(295739,32860,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük minibüste arkadaşlar için çok fazla ... yok.'::text,'yer'::text,'yerler'::text,'bir yer'::text,'Küçük minibüste arkadaşlar için çok fazla yer yok.'::text),
(295740,32860,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátoknak nincs sok ... a kis furgonban.'::text,'helyük'::text,'helyük'::text,'egy helyük'::text,'A barátoknak nincs sok helyük a kis furgonban.'::text),
(311979,34665,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Handy ... das Paar am weißen Strand.'::text,'filmt'::text,'filmen'::text,'filmend'::text,'Das Handy filmt das Paar am weißen Strand.'::text),
(311983,34665,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Телефон ... пару на білому пляжі.'::text,'знімає'::text,'знімати'::text,'знімаючи'::text,'Телефон знімає пару на білому пляжі.'::text),
(311982,34665,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El móvil ... a la pareja en la playa blanca.'::text,'graba'::text,'grabar'::text,'grabando'::text,'El móvil graba a la pareja en la playa blanca.'::text),
(311981,34665,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le téléphone ... le couple sur la plage blanche.'::text,'filme'::text,'filmer'::text,'filmant'::text,'Le téléphone filme le couple sur la plage blanche.'::text),
(311984,34665,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefon beyaz plajdaki çifti ...'::text,'kaydeder'::text,'kaydetmek'::text,'kaydederek'::text,'Telefon beyaz plajdaki çifti kaydeder.'::text),
(311985,34665,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A telefon ... a párt a fehér strandon.'::text,'felveszi'::text,'felvenni'::text,'felvevő'::text,'A telefon felveszi a párt a fehér strandon.'::text),
(311997,34667,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... ist das Handy, das sie filmt? Im Sand, Alter.'::text,'wo'::text,'wer'::text,'wann'::text,'Yo, wo ist das Handy, das sie filmt? Im Sand, Alter.'::text),
(312001,34667,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ... телефон, що їх знімає? У піску, бро.'::text,'де'::text,'хто'::text,'коли'::text,'Йо, де телефон, що їх знімає? У піску, бро.'::text),
(312000,34667,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿... está el móvil que los graba? En la arena, colega.'::text,'dónde'::text,'quién'::text,'cuándo'::text,'Tío, ¿dónde está el móvil que los graba? En la arena, colega.'::text),
(311999,34667,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... est le téléphone qui les filme ? Dans le sable, frérot.'::text,'où'::text,'qui'::text,'quand'::text,'Yo, où est le téléphone qui les filme ? Dans le sable, frérot.'::text),
(312002,34667,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hey, onları kaydeden telefon ...? Kumda, kanka.'::text,'nerede'::text,'kim'::text,'ne zaman'::text,'Hey, onları kaydeden telefon nerede? Kumda, kanka.'::text),
(312003,34667,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... van a telefon, ami felveszi őket? A homokban, haver.'::text,'hol'::text,'ki'::text,'mikor'::text,'Tesó, hol van a telefon, ami felveszi őket? A homokban, haver.'::text),
(312006,34668,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie hat das Handy gerichtet, sodass sie wieder ..., ohne Witz.'::text,'filmen werden'::text,'filmen werden'::text,'filmen'::text,'Alter, sie hat das Handy gerichtet, sodass sie wieder filmen werden, ohne Witz.'::text),
(312010,34668,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона полагодила телефон, тож вони знову ..., без жартів.'::text,'збираються знімати'::text,'зніматимуть'::text,'знімають'::text,'Бро, вона полагодила телефон, тож вони знову збираються знімати, без жартів.'::text),
(312009,34668,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella arregló el móvil, así que ... otra vez, en serio.'::text,'van a grabar'::text,'grabarán'::text,'graban'::text,'Tío, ella arregló el móvil, así que van a grabar otra vez, en serio.'::text),
(312008,34668,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle a réparé le téléphone, donc ils ... encore, sans mentir.'::text,'vont filmer'::text,'filmeront'::text,'filment'::text,'Frérot, elle a réparé le téléphone, donc ils vont filmer encore, sans mentir.'::text),
(312011,34668,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, telefonu düzeltti, bu yüzden yine ..., yemin ederim.'::text,'kaydedecekler'::text,'kaydedecekler'::text,'kaydederler'::text,'Kanka, telefonu düzeltti, bu yüzden yine kaydedecekler, yemin ederim.'::text),
(312012,34668,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, megjavította a telefont, szóval megint ..., komolyan.'::text,'fel fognak venni'::text,'fel fognak venni'::text,'felvesznek'::text,'Tesó, megjavította a telefont, szóval megint fel fognak venni, komolyan.'::text),
